172	// labelPair 是标签键值对字典序比较的单元。
173	type labelPair struct {
174		Key, Value string
175	}
176	
177	func sortedPairs(labels map[string]string) []labelPair {
178		keys := sortedKeys(labels)
179		pairs := make([]labelPair, len(keys))
180		for i, k := range keys {
181			pairs[i] = labelPair{Key: k, Value: labels[k]}
182		}
183		return pairs
184	}
185	
186	func compareLabelPairs(a, b []labelPair) int {
187		n := len(a)
188		if len(b) < n {
189			n = len(b)
190		}
191		for i := 0; i < n; i++ {
192			if a[i].Key != b[i].Key {
193				return strings.Compare(a[i].Key, b[i].Key)
194			}
195			if a[i].Value != b[i].Value {
196				return strings.Compare(a[i].Value, b[i].Value)
197			}
198		}
199		switch {
200		case len(a) < len(b):
201			return -1
202		case len(a) > len(b):
203			return 1
204		}
205		return 0
206	}
