968	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
969	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
970	func labelsMatch(want, stored map[string]string) bool {
971		for k, v := range want {
972			got, ok := stored[k]
973			if !ok || got != v {
974				return false
975			}
976		}
977		return true
978	}
979	
980	// matchSeries 筛出名称精确匹配且标签子集命中的已存序列，供三种查询操作各自整理；
981	// 只读，不改变存储。
982	func (s *MetricStore) matchSeries(q parsedQuery) []*storedSeries {
983		matched := make([]*storedSeries, 0)
984		for _, sr := range s.series {
985			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
986				continue
987			}
988			matched = append(matched, sr)
989		}
990		return matched
991	}
