993	// pointStats 是区间统计（query）与固定窗口统计（query_windows）共用的
994	// 点数与均值累计器：逐点累计个数与精确有理数总和。写入侧已保证值有限，
995	// SetFloat64 对有限值是精确的，因此求和与点的提交顺序、批次划分无关，
996	// 正负大数抵消后的微小余量不会丢失，总和超出 float64 有限范围时均值仍有限。
997	// 两种统计只在“哪些点归入哪一组”上不同，点数与均值规则统一由这里维护。
998	type pointStats struct {
999		count int
1000		sum   *big.Rat
1001		tmp   *big.Rat
1002	}
1003	
1004	func newPointStats() *pointStats {
1005		return &pointStats{sum: new(big.Rat), tmp: new(big.Rat)}
1006	}
1007	
1008	// add 把一个实际保存的 float64 采样值计入统计。
1009	func (a *pointStats) add(v float64) {
1010		a.count++
1011		a.sum.Add(a.sum, a.tmp.SetFloat64(v))
1012	}
1013	
1014	// reset 清空累计，供下一个互不影响的统计范围（如后一个窗口）复用同一累计器：
1015	// 前一个范围的点数与数值一律不带入后一个范围。
1016	func (a *pointStats) reset() {
1017		a.count = 0
1018		a.sum = new(big.Rat)
1019	}
1020	
1021	// average 返回精确算术平均舍入到最近可表示 float64 的结果（正中取偶；
1022	// 精确为零时返回 +0）。调用方保证至少 add 过一次。不改动累计状态。
1023	func (a *pointStats) average() float64 {
1024		return ratToFloat64NearestEven(new(big.Rat).Quo(a.sum, a.tmp.SetInt64(int64(a.count))))
1025	}
