1027	// runQuery 只读统计已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
1028	// 序列身份的整理（标签副本、排序键值对、排列次序）与写入快照共用同一套
1029	// organizeSeries 规则，只是入选范围不同：这里先按名称与标签条件筛出命中序列
1030	// 再整理，不为无关指标承担展示准备；筛后剩余序列的相对次序因此与写入全量
1031	// 结果一致。查询只返回每条序列的点数与均值，不构造采样明细列表（明细由
1032	// query_points 操作提供）——单次遍历点表直接累计进 pointStats（计数与
1033	// 均值都与点的排列次序无关）。区间内没有点的序列不列出，不补零值条目。
1034	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
1035		organized := organizeSeries(s.matchSeries(q))
1036	
1037		out := make([]QuerySeries, 0, len(organized))
1038		for _, entry := range organized {
1039			// 一次遍历直接统计：不构造值切片、不排序时间戳，避免为只返回
1040			// count/average 的查询承担采样明细展示。点数与均值的累计和舍入
1041			// 规则与固定窗口统计共用 pointStats。
1042			stats := newPointStats()
1043			for ts, v := range entry.sr.points {
1044				if ts < q.start || ts > q.end {
1045					continue
1046				}
1047				stats.add(v)
1048			}
1049			if stats.count == 0 {
1050				continue
1051			}
1052			out = append(out, QuerySeries{
1053				Name:    entry.ref.Name,
1054				Labels:  entry.ref.Labels,
1055				Count:   stats.count,
1056				Average: stats.average(),
1057			})
1058		}
1059		return &QueryResult{Status: "ok", Op: "query", Series: out}
1060	}
