1087	// seriesPointsInRange 按 timestamp 升序返回一条已存序列在 [start,end] 闭区间
1088	// 内的采样点，供采样明细查询展示。选取、升序排列与点构造与写入快照共用
1089	// seriesPoints，区别只在传入的选取范围是闭区间而不是全部。
1090	func seriesPointsInRange(sr *storedSeries, start, end int64) []Point {
1091		return seriesPoints(sr, func(ts int64) bool { return ts >= start && ts <= end })
1092	}
