1094	// runQueryWindows 只读统计固定时间窗口内的点数与均值：窗口把 [start,end]
1095	// 闭区间按 step 毫秒从 start 起连续划分，第 k 个窗口为
1096	// [start+k*step, start+(k+1)*step-1]（含首尾毫秒），最后一个截到 end，
1097	// 各序列共用同一组由 start 与 step 决定的边界——因此不为空窗口构造任何条目，
1098	// 即使区间横跨整个 int64 也不预先物化窗口表。
1099	//
1100	// 名称精确、标签子集的序列筛选与 organizeSeries 整理、序列排列次序和另两种
1101	// 查询完全一致。每条序列独立统计：先取区间内按时间戳升序的采样点，升序点流
1102	// 中落在同一窗口的点必然连续，据此一次遍历分窗，逐窗口用 pointStats 累计
1103	// 点数与均值——与区间统计共用同一套计数、精确求和与舍入规则；窗口切换时
1104	// reset，前一窗口的点数与数值不带入后一窗口。只输出实际有点的窗口，按窗口
1105	// 起点升序，空窗口不补零，整个区间没有点的序列不列出，无任何命中时 series
1106	// 为空数组。每个点只归入 floor((ts-start)/step) 唯一窗口；start==end 时所有
1107	// 点归入唯一窗口。平均值依据实际存储的 float64 值计算，正负大数抵消或总和
1108	// 超出 float64 范围时仍得有限结果。查询只读，不改变存储。
1109	func (s *MetricStore) runQueryWindows(q parsedQuery) *QueryWindowsResult {
1110		organized := organizeSeries(s.matchSeries(q))
1111	
1112		// diff = end - start，可能达到 2^64-1（start 为 MinInt64、end 为 MaxInt64），
1113		// 只能以 uint64 承载；窗口下标与窗口内偏移都在这个无符号区间内运算。
1114		diff := uint64(q.end) - uint64(q.start)
1115	
1116		out := make([]QueryWindowsSeries, 0, len(organized))
1117		for _, entry := range organized {
1118			points := seriesPointsInRange(entry.sr, q.start, q.end)
1119			if len(points) == 0 {
1120				continue
1121			}
1122			windows := make([]Window, 0)
1123			var curIdx uint64
1124			stats := newPointStats()
1125			flush := func() {
1126				windows = append(windows, buildWindow(q.start, q.end, q.step, diff, curIdx, stats))
1127			}
1128			for i, p := range points {
1129				// 无符号偏移除以 step 得窗口下标；升序点流下标单调不减。
1130				idx := (uint64(p.Timestamp) - uint64(q.start)) / uint64(q.step)
1131				if i > 0 && idx != curIdx {
1132					flush()
1133					stats.reset()
1134				}
1135				curIdx = idx
1136				stats.add(p.Value)
1137			}
1138			flush()
1139			out = append(out, QueryWindowsSeries{
1140				Name:    entry.ref.Name,
1141				Labels:  entry.ref.Labels,
1142				Windows: windows,
1143			})
1144		}
1145		return &QueryWindowsResult{Status: "ok", Op: "query_windows", Series: out}
1146	}
1147	
1148	// buildWindow 构造一个非空窗口的统计：窗口起点是 start + idx*step，终点是
1149	// 起点加 step 减一；起点加 step 减一越过查询区间（含无符号加法溢出）时截到
1150	// end。点数与均值取自该窗口独立累计的 stats，均值按与 query 相同的精确平均
1151	// 与居中取偶规则得出（精确为零返回 +0）。调用方保证 0 <= idx*step <= diff，
1152	// 且 stats 至少计入了一个点。
1153	func buildWindow(start, end, step int64, diff, idx uint64, stats *pointStats) Window {
1154		startOff := idx * uint64(step)
1155		wStart := int64AtOffset(start, startOff)
1156		wEnd := end
1157		// tail <= diff-startOff 的比较不做 startOff+tail 加法，避免无符号溢出
1158		// （step 接近 2^63 时朴素相加可能绕过 2^64）。
1159		if tail := uint64(step) - 1; tail <= diff-startOff {
1160			wEnd = int64AtOffset(start, startOff+tail)
1161		}
1162		return Window{
1163			Start:   wStart,
1164			End:     wEnd,
1165			Count:   stats.count,
1166			Average: stats.average(),
1167		}
1168	}
1169	
1170	// int64AtOffset 返回 start + off（0 <= off，且调用方保证结果不超过 MaxInt64）。
1171	// 直接做有符号相加在 start 接近 int64 下界、off 很大时会溢出，因此统一走
1172	// 无符号运算还原：start 非负时无符号相加必落在非负有符号范围；start 为负时
1173	// 以 -start 为界先回到非正区间、再跨入正区间，两个分支都不产生溢出。
1174	func int64AtOffset(start int64, off uint64) int64 {
1175		if start >= 0 {
1176			return int64(uint64(start) + off)
1177		}
1178		gap := uint64(-start) // 0 < gap <= 2^63（start 为 MinInt64 时恰为 2^63）
1179		if off <= gap {
1180			// gap-off 为 2^63 时 int64 表示恰为 MinInt64，取负仍是 MinInt64，语义正确。
1181			return -int64(gap - off)
1182		}
1183		return int64(off - gap)
1184	}
1185	
1186	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
1187	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
1188	func ratToFloat64NearestEven(x *big.Rat) float64 {
1189		if x.Sign() == 0 {
1190			return 0
1191		}
1192		num := new(big.Int).Set(x.Num())
1193		den := x.Denom()
1194		neg := num.Sign() < 0
1195		if neg {
1196			num.Neg(num)
1197		}
1198	
1199		// e 满足 2^e <= num/den < 2^(e+1)。
1200		e := floorLog2Rat(num, den)
1201		var m *big.Int
1202		scale := 0
1203		if e >= -1022 {
1204			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
1205			scale = e - 52
1206			m = roundScaledRatio(num, den, scale)
1207			if m.BitLen() == 54 {
1208				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
1209				m.Rsh(m, 1)
1210				scale++
1211			}
1212		} else {
1213			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
1214			scale = -1074
1215			m = roundScaledRatio(num, den, scale)
1216		}
1217		// m < 2^53，可以精确放入 int64 与 float64。
1218		f := math.Ldexp(float64(m.Int64()), scale)
1219		if neg {
1220			return -f
1221		}
1222		return f
1223	}
1224	
1225	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
1226	func floorLog2Rat(num, den *big.Int) int {
1227		k := num.BitLen() - den.BitLen()
1228		var t big.Int
1229		if k >= 0 {
1230			t.Lsh(den, uint(k))
1231			if num.Cmp(&t) >= 0 {
1232				return k
1233			}
1234			return k - 1
1235		}
1236		t.Lsh(num, uint(-k))
1237		if t.Cmp(den) >= 0 {
1238			return k
1239		}
1240		return k - 1
1241	}
1242	
1243	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
1244	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
1245		n := new(big.Int).Set(num)
1246		d := new(big.Int).Set(den)
1247		if scale >= 0 {
1248			d.Lsh(d, uint(scale))
1249		} else {
1250			n.Lsh(n, uint(-scale))
1251		}
1252		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
1253		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
1254		case 1:
1255			q.Add(q, big.NewInt(1))
1256		case 0:
1257			if q.Bit(0) == 1 {
1258				q.Add(q, big.NewInt(1))
1259			}
1260		}
1261		return q
1262	}
