1264	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
1265	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
1266	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
1267	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
1268	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
1269	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
1270	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
1271	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
1272	func (r SeriesRef) String() string {
1273		var b strings.Builder
1274		b.WriteString(identityText(r.Name))
1275		b.WriteByte('{')
1276		for i, p := range sortedPairs(r.Labels) {
1277			if i > 0 {
1278				b.WriteByte(',')
1279			}
1280			b.WriteString(identityText(p.Key))
1281			b.WriteByte('=')
1282			b.WriteString(identityText(p.Value))
1283		}
1284		b.WriteByte('}')
1285		return b.String()
1286	}
1287	
1288	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
1289	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
1290	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
1291	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
1292	// 因此渲染结果不会把内容字符误读为标签边界。
1293	func identityText(s string) string {
1294		if s == "" || s != strings.TrimSpace(s) {
1295			return strconv.Quote(s)
1296		}
1297		for _, r := range s {
1298			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
1299				return strconv.Quote(s)
1300			}
1301		}
1302		return s
1303	}
1304	
1305	// organizedSeries 是结果整理中的一条序列：携带已存序列指针、
1306	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
1307	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
1308	// 整理好的键值对，供排序比较直接复用。写入快照与区间查询都经由
1309	// organizeSeries 得到这样的条目，区别只在入选的序列范围。
1310	type organizedSeries struct {
1311		sr    *storedSeries
1312		ref   SeriesRef
1313		pairs []labelPair
1314	}
1315	
1316	// seriesLess 是写入快照与区间查询共用的序列次序约定：先按指标名字符串
1317	// 字典序，同名再按标签键升序后的键值对逐对比较（先比键再比值，前一对
1318	// 相同才比下一对；较短集合是完整前缀时排前，无标签序列因此排在最前）。
1319	// 标签值按字符串比较（"10" 在 "2" 之前）。排序只看解析后的真实身份，
1320	// 与冲突原因里的展示文字、标签的输入次序无关。
1321	func seriesLess(a, b organizedSeries) bool {
1322		if a.ref.Name != b.ref.Name {
1323			return a.ref.Name < b.ref.Name
1324		}
1325		return compareLabelPairs(a.pairs, b.pairs) < 0
1326	}
1327	
1328	// organizeSeries 是写入快照与三种查询成功结果共用的序列身份整理：对入选的每条已存序列
1329	// 复制独立的标签副本、预整理按键升序的键值对，并按 seriesLess 的统一次序
1330	// 排列。入选范围由调用方决定：写入快照传入全部已提交序列，三种区间查询只
1331	// 传入名称与标签条件命中的序列；它们因此遵循同一套整理规则而各自保留数据
1332	// 范围。每条序列的标签只在入选时整理一次：排序后的键值对随条目保留，sort
1333	// 的反复比较直接复用同一份结果，不会因一条序列参与多次比较而反复整理同一
1334	// 套标签。整理结果不复制采样点；写入快照的采样点选取与升序排列由
1335	// allSeriesPoints 完成，均值查询只在点表上计数与求和，采样明细查询由
1336	// seriesPointsInRange 按区间选取并升序排列，固定窗口查询在区间升序点流上
1337	// 按窗口累计计数与精确求和。
1338	func organizeSeries(selected []*storedSeries) []organizedSeries {
1339		out := make([]organizedSeries, 0, len(selected))
1340		for _, sr := range selected {
1341			// 标签必须复制：成功结果是当次操作的独立记录，
1342			// 调用方修改结果标签不能改动已存序列的身份。
1343			labels := cloneLabels(sr.ref.Labels)
1344			out = append(out, organizedSeries{
1345				sr:    sr,
1346				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
1347				pairs: sortedPairs(labels),
1348			})
1349		}
1350		sort.Slice(out, func(i, j int) bool { return seriesLess(out[i], out[j]) })
1351		return out
1352	}
1353	
1354	// allSeriesPoints 按 timestamp 升序返回一条已存序列的全部采样点，供写入快照
1355	// 展示。选取、升序排列与点构造与采样明细查询共用 seriesPoints，区别只在传入
1356	// 的选取范围是全部而不是闭区间。
1357	func allSeriesPoints(sr *storedSeries) []Point {
1358		return seriesPoints(sr, nil)
1359	}
1360	
1361	// seriesPoints 是写入快照与采样明细查询共用的采样点整理：从已存序列的点表中
1362	// 选出 keep 命中的时间戳（keep 为 nil 表示全部选取），按 timestamp 升序排列，
1363	// 每个时间戳配上点表中实际存储的 value（数值与时间戳一一对应，排序只动时间戳
1364	// 列表、不重配对值；int64 比较保留整数精度，float64 原样取出，负零保持负零）。
1365	// 返回的是新建切片与新建 Point，不持有点表的任何引用：调用方对结果的修改不
1366	// 影响存储，也不影响此前或此后取得的其他成功结果；取得结果后再写入新点，该份
1367	// 结果也不跟随存储变化。均值查询不构造这样的明细列表，只在点表上计数与求和。
1368	func seriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
1369		tsList := make([]int64, 0, len(sr.points))
1370		for ts := range sr.points {
1371			if keep != nil && !keep(ts) {
1372				continue
1373			}
1374			tsList = append(tsList, ts)
1375		}
1376		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
1377		points := make([]Point, len(tsList))
1378		for i, ts := range tsList {
1379			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
1380		}
1381		return points
1382	}
1383	
1384	// snapshot 生成按规范排序的全部序列视图：入选范围是全部已提交序列，
1385	// 身份整理与次序来自 organizeSeries，点排列来自 allSeriesPoints；
1386	// 三种区间查询共用同一套身份整理，各自只对命中序列统计均值、列出明细或
1387	// 按固定窗口统计。
1388	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
1389		all := make([]*storedSeries, 0, len(s.series))
1390		for _, sr := range s.series {
1391			all = append(all, sr)
1392		}
1393		organized := organizeSeries(all)
1394		views := make([]SeriesView, 0, len(organized))
1395		for _, os := range organized {
1396			views = append(views, SeriesView{
1397				Name:   os.ref.Name,
1398				Labels: os.ref.Labels,
1399				Points: allSeriesPoints(os.sr),
1400			})
1401		}
1402		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
1403	}
1404

