133			// ts 在 start-1..end+1 内抽取，顺带验证区间外的点既不入窗也不影响计数。
134			width := int(end-start) + 3
135			perm := rng.Perm(width)
136			n := 1 + rng.Intn(width)
137			inRange := map[int64]bool{}
138			line := "["
