155					t.Fatalf("iter %d: expected empty series, got %+v", iter, res.Series)
156				}
157				continue
158			}
159			if len(res.Series) != 1 {
160				t.Fatalf("iter %d: expected exactly one series, got %+v", iter, res.Series)
161			}
162			wins := res.Series[0].Windows
163			// 期望分组：朴素 uint64 下标（区间宽度小于 2^63，下标不会接近 uint64 上界）。
164			type gw struct {
