182				if we > end || we < ws {
183					we = end
184				}
185				if i := indexOf(ws, we); i >= 0 {
186					want[i].c++
187				} else {
188					want = append(want, gw{ws, we, 1})
189				}
190			}
191			// 期望按起点升序。
192			for i := 1; i < len(want); i++ {
193				for j := i; j > 0 && want[j].s < want[j-1].s; j-- {
194					want[j], want[j-1] = want[j-1], want[j]
195				}
196			}
197			if len(wins) != len(want) {
198				t.Fatalf("iter %d [%d,%d] step %d: got %d windows, want %d: %+v vs %+v",
199					iter, start, end, step, len(wins), len(want), wins, want)
200			}
201			for i := range want {
202				if wins[i].Start != want[i].s || wins[i].End != want[i].e || wins[i].Count != want[i].c {
203					t.Fatalf("iter %d window %d = [%d,%d] c=%d avg=%v, want [%d,%d] c=%d",
204						iter, i, wins[i].Start, wins[i].End, wins[i].Count, wins[i].Average,
205						want[i].s, want[i].e, want[i].c)
206				}
207				if i > 0 && wins[i].Start <= wins[i-1].End {
208					t.Fatalf("iter %d: windows overlap/out of order: %+v", iter, wins)
209				}
210			}
211		}
212	}
