package darksafe

import (
	"math/big"
	"math/rand"
	"testing"
)

// 用 big.Int 参考实现核对窗口边界与窗口归属，覆盖接近 int64 上下界的区间。
func TestQueryWindowsReferenceDifferential(t *testing.T) {
	cases := []struct {
		start, end, step int64
		ts               []int64
	}{
		{tsMinInt64, tsMaxInt64, tsMaxInt64, []int64{tsMinInt64, -2, -1, 0, 1, tsMaxInt64}},
		{tsMinInt64, tsMaxInt64, 1, []int64{tsMinInt64, 0, tsMaxInt64}},
		{-5, 4, 3, []int64{-5, -4, -1, 0, 1, 4}},
		{1000, 3000, 1000, []int64{1000, 1999, 2000, 2999, 3000}},
		{0, tsMaxInt64, tsMaxInt64, []int64{0, tsMaxInt64 - 1, tsMaxInt64}},
		{tsMinInt64, tsMinInt64 + 10, 3, []int64{tsMinInt64, tsMinInt64 + 2, tsMinInt64 + 10}},
		{tsMaxInt64 - 5, tsMaxInt64, 3, []int64{tsMaxInt64 - 5, tsMaxInt64 - 3, tsMaxInt64}},
		{-10, 10, 7, []int64{-10, -4, -3, 3, 10}},
	}
	bStart := big.NewInt(0)
	bEnd := big.NewInt(0)
	bStep := big.NewInt(0)
	bOne := big.NewInt(1)
	for _, tc := range cases {
		store := NewMetricStore()
		line := "["
		for i, ts := range tc.ts {
			if i > 0 {
				line += ","
			}
			line += sample("m", ts, float64(i+1), nil)
		}
		line += "]"
		mustOK(t, store, line)
		res := mustQueryWindows(t, store, queryWindowsAll("m", tc.start, tc.end, tc.step))

		// 参考分组：idx = (ts-start)/step（大整数整除），逐组累计点。
		// idx 最大可达 2^64-1（step=1、跨整个 int64 区间），只能以 uint64 承载。
		bStart.SetInt64(tc.start)
		bEnd.SetInt64(tc.end)
		bStep.SetInt64(tc.step)
		groups := map[uint64][]int64{} // idx → timestamps
		var order []uint64
		for _, ts := range tc.ts {
			if ts < tc.start || ts > tc.end {
				continue
			}
			bTS := big.NewInt(ts)
			idx := new(big.Int).Sub(bTS, bStart)
			idx.Quo(idx, bStep)
			if !idx.IsUint64() {
				t.Fatalf("window idx overflows uint64: %v", idx)
			}
			k := idx.Uint64()
			if _, ok := groups[k]; !ok {
				order = append(order, k)
			}
			groups[k] = append(groups[k], ts)
		}

		if len(res.Series) != 1 {
			t.Fatalf("range [%d,%d] step %d: series = %+v", tc.start, tc.end, tc.step, res.Series)
		}
		got := res.Series[0].Windows
		if len(got) != len(order) {
			t.Fatalf("range [%d,%d] step %d: got %d windows %+v, want %d",
				tc.start, tc.end, tc.step, len(got), got, len(order))
		}
		for i, k := range order {
			// wStart = start + k*step；wEnd = min(wStart+step-1, end)。
			ws := new(big.Int).Mul(new(big.Int).SetUint64(k), bStep)
			ws.Add(ws, bStart)
			we := new(big.Int).Add(ws, bStep)
			we.Sub(we, bOne)
			if we.Cmp(bEnd) > 0 {
				we.Set(bEnd)
			}
			if !ws.IsInt64() || !we.IsInt64() {
				t.Fatalf("window bounds overflow int64: [%v,%v]", ws, we)
			}
			if got[i].Start != ws.Int64() || got[i].End != we.Int64() {
				t.Fatalf("window %d bounds = [%d,%d], want [%d,%d]",
					k, got[i].Start, got[i].End, ws.Int64(), we.Int64())
			}
			if got[i].Count != len(groups[k]) {
				t.Fatalf("window %d count = %d, want %d", k, got[i].Count, len(groups[k]))
			}
			// 检查窗口不倒置、不越界。
			if got[i].Start > got[i].End || got[i].Start < tc.start || got[i].End > tc.end {
				t.Fatalf("invalid window %+v within [%d,%d]", got[i], tc.start, tc.end)
			}
			// 平均 = (i+1) 的简单平均核对。
			var sum float64
			for _, ts := range groups[k] {
				for j, x := range tc.ts {
					if x == ts {
						sum += float64(j + 1)
					}
				}
			}
			if got[i].Average != sum/float64(len(groups[k])) {
				t.Fatalf("window %d average = %v, want %v", k, got[i].Average, sum/float64(len(groups[k])))
			}
		}
	}
}

// TestQueryWindowsRandomizedTiling 随机生成区间、步长与时间戳（含负数与接近
// int64 边界的值），直接核对输出窗口的归属、边界、截断与升序，不依赖参考分组。
func TestQueryWindowsRandomizedTiling(t *testing.T) {
	rng := rand.New(rand.NewSource(20261006))
	for iter := 0; iter < 300; iter++ {
		var start, end, step int64
		if rng.Intn(5) == 0 {
			// 极端分支：起点贴近 int64 下界、小区间、步长取 int64 上界。
			start = tsMinInt64 + int64(rng.Intn(5))
			end = start + int64(rng.Intn(5))
			step = tsMaxInt64
		} else {
			// 普通分支：起点限制在 2^60 内，保证 start+宽度 不会溢出 int64。
			start = rng.Int63n(2 << 59)
			if rng.Intn(2) == 0 {
				start = -start
			}
			end = start + int64(rng.Intn(40)) // 小区间，宽度为 0..39
			step = int64(1 + rng.Intn(50))
		}
		// 每个时间戳只写一次、值统一为 1（避免同位置冲突；计数按去重后的点）。
		// ts 在 start-1..end+1 内抽取，顺带验证区间外的点既不入窗也不影响计数。
		width := int(end-start) + 3
		perm := rng.Perm(width)
		n := 1 + rng.Intn(width)
		inRange := map[int64]bool{}
		line := "["
		for i := 0; i < n; i++ {
			ts := start - 1 + int64(perm[i])
			if i > 0 {
				line += ","
			}
			line += sample("m", ts, 1, nil)
			if ts >= start && ts <= end {
				inRange[ts] = true
			}
		}
		line += "]"
		store := NewMetricStore()
		mustOK(t, store, line)
		res := mustQueryWindows(t, store, queryWindowsAll("m", start, end, step))
		if len(inRange) == 0 {
			if len(res.Series) != 0 {
				t.Fatalf("iter %d: expected empty series, got %+v", iter, res.Series)
			}
			continue
		}
		if len(res.Series) != 1 {
			t.Fatalf("iter %d: expected exactly one series, got %+v", iter, res.Series)
		}
		wins := res.Series[0].Windows
		// 期望分组：朴素 uint64 下标（区间宽度小于 2^63，下标不会接近 uint64 上界）。
		type gw struct {
			s, e int64
			c    int
		}
		var want []gw
		indexOf := func(s, e int64) int {
			for i := range want {
				if want[i].s == s && want[i].e == e {
					return i
				}
			}
			return -1
		}
		for ts := range inRange {
			off := uint64(ts) - uint64(start)
			k := off / uint64(step)
			ws := int64(uint64(start) + k*uint64(step))
			we := ws + step - 1
			if we > end || we < ws {
				we = end
			}
			if i := indexOf(ws, we); i >= 0 {
				want[i].c++
			} else {
				want = append(want, gw{ws, we, 1})
			}
		}
		// 期望按起点升序。
		for i := 1; i < len(want); i++ {
			for j := i; j > 0 && want[j].s < want[j-1].s; j-- {
				want[j], want[j-1] = want[j-1], want[j]
			}
		}
		if len(wins) != len(want) {
			t.Fatalf("iter %d [%d,%d] step %d: got %d windows, want %d: %+v vs %+v",
				iter, start, end, step, len(wins), len(want), wins, want)
		}
		for i := range want {
			if wins[i].Start != want[i].s || wins[i].End != want[i].e || wins[i].Count != want[i].c {
				t.Fatalf("iter %d window %d = [%d,%d] c=%d avg=%v, want [%d,%d] c=%d",
					iter, i, wins[i].Start, wins[i].End, wins[i].Count, wins[i].Average,
					want[i].s, want[i].e, want[i].c)
			}
			if i > 0 && wins[i].Start <= wins[i-1].End {
				t.Fatalf("iter %d: windows overlap/out of order: %+v", iter, wins)
			}
		}
	}
}

package darksafe

import (
	"encoding/json"
	"fmt"
	"math"
	"reflect"
	"strings"
	"testing"
)

// 本文件回归保障只读操作 query_windows：沿用 query 的查询条件（name 精确、
// labels 子集、[start,end] 闭区间）与序列整理/排列规则，但把区间按 step
// 毫秒从 start 起连续划分成含首尾毫秒的固定窗口，逐序列、逐窗口输出实际有点
// 窗口的 start、end、count、average。核心约定：
//
//   - 窗口为 [start+k*step, start+(k+1)*step-1]，最后一个截到 end；
//     区间 [1000,3000]、step 1000 时窗口为 [1000,1999]、[2000,2999]、[3000,3000]；
//   - 各序列共用同一组边界；每个点只归入一个窗口；start == end 时只有一个窗口；
//   - 只输出实际有点的窗口，按窗口起点升序，空窗口不补零；整个区间没有点的
//     序列不列出；无匹配时 series 为非 nil 空数组；
//   - 每条 series 保留完整指标名与完整标签集合，序列排列次序与另两种查询一致；
//   - count 统计窗口内已成功保存的点；average 沿用 query 的精确有理数平均与
//     居中取偶舍入，依据实际存储的 float64 值；
//   - step 必须是大于零且在 int64 范围内的 JSON 整数，且只用于 query_windows；
//   - 即使 start/end 接近 int64 上下界、step 接近 int64 上界，窗口也不溢出、
//     不倒置、不遗漏采样；
//   - 查询只读；失败是查询错误（无 index、无 conflict、无 series），保留行号，
//     后续输入照常处理；query 与 query_points 的行为保持兼容。

// mustQueryWindows 要求 query_windows 查询成功并返回窗口结果。
func mustQueryWindows(t *testing.T, store *MetricStore, line string) *QueryWindowsResult {
	t.Helper()
	res, err := store.QueryWindowsLine(line)
	if err != nil {
		t.Fatalf("expected query_windows success for %s, got error: %+v", line, err)
	}
	return res
}

// mustQueryWindowsFail 要求 query_windows 查询失败并返回结构化错误。
func mustQueryWindowsFail(t *testing.T, store *MetricStore, line string) *LineError {
	t.Helper()
	res, err := store.QueryWindowsLine(line)
	if err == nil {
		t.Fatalf("expected query_windows failure for %s, got result: %+v", line, res)
	}
	return err
}

// queryWindowsAll 构造省略 labels 的 query_windows 对象文本。
func queryWindowsAll(name string, start, end, step int64) string {
	return fmt.Sprintf(`{"op":"query_windows","name":%s,"start":%d,"end":%d,"step":%d}`,
		jsonString(name), start, end, step)
}

// queryWindowsLabels 构造按标签子集查询的 query_windows 对象文本。
func queryWindowsLabels(name string, start, end, step int64, labels map[string]string) string {
	return `{"op":"query_windows","name":` + jsonString(name) +
		fmt.Sprintf(`,"start":%d,"end":%d,"step":%d,"labels":`, start, end, step) +
		jsonLabels(labels) + `}`
}

func window(start, end int64, count int, avg float64) Window {
	return Window{Start: start, End: end, Count: count, Average: avg}
}

// assertWindows 断言一条序列的窗口列表与预期完全一致（含顺序）。
func assertWindows(t *testing.T, got []Window, want []Window, note string) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("%s: windows = %+v, want %+v", note, got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("%s: window[%d] = %+v, want %+v (full got %+v)", note, i, got[i], want[i], got)
		}
	}
}

// TestQueryWindowsSpecExample 任务书示例：区间 [1000,3000]、step 1000 时窗口为
// [1000,1999]、[2000,2999]、[3000,3000]，空窗口不补零。
func TestQueryWindowsSpecExample(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, "["+
		sample("cpu", 1000, 2, nil)+","+
		sample("cpu", 1500, 4, nil)+","+
		sample("cpu", 2000, 6, nil)+","+
		sample("cpu", 3000, 8, nil)+"]")

	res := mustQueryWindows(t, store, queryWindowsAll("cpu", 1000, 3000, 1000))
	if res.Status != "ok" || res.Op != "query_windows" {
		t.Fatalf("status/op = %q/%q, want ok/query_windows", res.Status, res.Op)
	}
	if len(res.Series) != 1 {
		t.Fatalf("series = %+v, want exactly one", res.Series)
	}
	s0 := res.Series[0]
	if s0.Name != "cpu" {
		t.Fatalf("series name = %q, want cpu", s0.Name)
	}
	assertWindows(t, s0.Windows, []Window{
		window(1000, 1999, 2, 3),
		window(2000, 2999, 1, 6),
		window(3000, 3000, 1, 8),
	}, "spec windows [1000,3000] step 1000")
}

// TestQueryWindowsResultShape 锁定成功结果的 JSON 形状：op 为 query_windows，
// 序列条目只有 name、labels、windows；窗口只有 start、end、count、average；
// 无命中时 series 是空数组而不是 null。
func TestQueryWindowsResultShape(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)

	res := mustQueryWindows(t, store, queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "a"}))
	raw := marshalCompact(t, res)
	want := `{"status":"ok","op":"query_windows","series":[` +
		`{"name":"cpu","labels":{"host":"a"},"windows":[` +
		`{"start":1000,"end":1999,"count":1,"average":2}]}]}`
	if raw != want {
		t.Fatalf("query_windows JSON = %s, want %s", raw, want)
	}
	var decoded map[string]any
	if err := json.Unmarshal([]byte(raw), &decoded); err != nil {
		t.Fatal(err)
	}
	entry := decoded["series"].([]any)[0].(map[string]any)
	for _, banned := range []string{"count", "average", "points"} {
		if _, ok := entry[banned]; ok {
			t.Fatalf("query_windows series entry must not carry %q: %v", banned, entry)
		}
	}
	w0 := entry["windows"].([]any)[0].(map[string]any)
	if _, ok := w0["timestamp"]; ok {
		t.Fatalf("window must not carry timestamp: %v", w0)
	}

	// 无命中：成功的空 series 数组（非 null）。
	res = mustQueryWindows(t, store, queryWindowsAll("cpu", 2000, 3000, 1000))
	if res.Series == nil || len(res.Series) != 0 {
		t.Fatalf("miss query_windows = %+v, want non-nil empty series list", res.Series)
	}
	if raw = marshalCompact(t, res); raw != `{"status":"ok","op":"query_windows","series":[]}` {
		t.Fatalf("empty query_windows JSON = %s, want empty series array", raw)
	}
}

// TestQueryWindowsEmptyWindowsOmitted 空窗口不补零：只有实际有点的窗口列出，
// 窗口按起点升序；整条序列区间内没有点时不列出；无匹配序列时 series 为空。
func TestQueryWindowsEmptyWindowsOmitted(t *testing.T) {
	store := NewMetricStore()
	// host=a：窗口 0、2 有点，窗口 1 为空；host=b：整个区间没有点。
	mustOK(t, store, `[
		{"name":"cpu","timestamp":0,"value":2,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":1,"value":4,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":20,"value":6,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":21,"value":10,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":99,"value":1,"labels":{"host":"b"}}
	]`)

	// labels 子集 host=a：只列窗口 0 与窗口 2，空窗口 1 不补零。
	res := mustQueryWindows(t, store, queryWindowsLabels("cpu", 0, 29, 10, map[string]string{"host": "a"}))
	if len(res.Series) != 1 {
		t.Fatalf("series = %+v, want exactly host=a", res.Series)
	}
	assertWindows(t, res.Series[0].Windows, []Window{
		window(0, 9, 2, 3),
		window(20, 29, 2, 8),
	}, "empty middle window omitted")

	// 省略 labels 命中全部序列：host=b 在 [0,29] 内没有点，整个序列不列出。
	res = mustQueryWindows(t, store, queryWindowsAll("cpu", 0, 29, 10))
	if len(res.Series) != 1 || res.Series[0].Labels["host"] != "a" {
		t.Fatalf("series = %+v, want only host=a (host=b has no in-range points)", res.Series)
	}

	// 指标不存在 / 标签未命中 / 区间内无点：都是成功的空 series。
	for name, line := range map[string]string{
		"unknown metric":   queryWindowsAll("nope", 0, 29, 10),
		"label miss":       queryWindowsLabels("cpu", 0, 29, 10, map[string]string{"host": "zzz"}),
		"no points in itv": queryWindowsAll("cpu", 30, 40, 10),
	} {
		t.Run(name, func(t *testing.T) {
			r := mustQueryWindows(t, store, line)
			if r.Series == nil || len(r.Series) != 0 {
				t.Fatalf("%s: series = %+v, want empty", name, r.Series)
			}
		})
	}
}

// TestQueryWindowsSingleTimestamp start == end 时区间只有唯一窗口；落在该
// 时间戳上的点全部归入它，窗口终点等于 start。
func TestQueryWindowsSingleTimestamp(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, "["+
		sample("m", 5000, 2, nil)+","+
		sample("m", 5000, 2.0, nil)+"]") // 第二个是同值重复，不新增点

	res := mustQueryWindows(t, store, queryWindowsAll("m", 5000, 5000, 1))
	assertWindows(t, res.Series[0].Windows, []Window{window(5000, 5000, 1, 2)},
		"start==end, step=1")

	// step 远大于单点区间时唯一窗口仍是 [start,start]。
	res = mustQueryWindows(t, store, queryWindowsAll("m", 5000, 5000, tsMaxInt64))
	assertWindows(t, res.Series[0].Windows, []Window{window(5000, 5000, 1, 2)},
		"start==end, huge step")

	// 单点区间无点：空 series。
	res = mustQueryWindows(t, store, queryWindowsAll("m", 5001, 5001, 1))
	if len(res.Series) != 0 {
		t.Fatalf("series = %+v, want empty", res.Series)
	}
}

// TestQueryWindowsBoundariesAndAssignment 校验首尾毫秒归属：每个点只归入一个
// 窗口，窗口边界点（start+k*step - 1 与 start+k*step）分别落在相邻窗口。
func TestQueryWindowsBoundariesAndAssignment(t *testing.T) {
	store := NewMetricStore()
	// [10,39]、step=10：窗口 [10,19]、[20,29]、[30,39]，每个关键边界一个点。
	mustOK(t, store, `[
		{"name":"m","timestamp":10,"value":1},
		{"name":"m","timestamp":19,"value":3},
		{"name":"m","timestamp":20,"value":5},
		{"name":"m","timestamp":29,"value":7},
		{"name":"m","timestamp":30,"value":9},
		{"name":"m","timestamp":39,"value":11}
	]`)
	res := mustQueryWindows(t, store, queryWindowsAll("m", 10, 39, 10))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(10, 19, 2, 2),
		window(20, 29, 2, 6),
		window(30, 39, 2, 10),
	}, "each boundary ms belongs to exactly one window")

	// 区间不是 step 的整数倍：最后一个窗口截到 end，而不是 end 对齐的完整窗口。
	res = mustQueryWindows(t, store, queryWindowsAll("m", 10, 35, 10))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(10, 19, 2, 2),
		window(20, 29, 2, 6),
		window(30, 35, 1, 9), // 39 上的点不在区间；窗口截到 35
	}, "last window clipped to end")

	// 区间比 step 宽但不足两个窗口：第一个完整窗口 + 长度为 1 的收尾窗口。
	res = mustQueryWindows(t, store, queryWindowsAll("m", 10, 20, 10))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(10, 19, 2, 2),
		window(20, 20, 1, 5),
	}, "width == step yields two windows touching at the boundary")

	// step 大于区间宽度：唯一窗口就是整个区间（截到 end）。
	res = mustQueryWindows(t, store, queryWindowsAll("m", 10, 39, 100))
	assertWindows(t, res.Series[0].Windows, []Window{window(10, 39, 6, 6)},
		"step wider than the range")
}

// TestQueryWindowsLabelsIdentityAndOrder 名称与标签筛选沿用现有查询：子集匹配、
// 完整标签集合保留、序列排列次序与 query/query_points 一致（先名字后排序标签）。
func TestQueryWindowsLabelsIdentityAndOrder(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":20,"value":2,"labels":{"zone":"x","host":"h"}},
		{"name":"m","timestamp":10,"value":1},
		{"name":"m","timestamp":30,"value":3,"labels":{"zone":"x"}},
		{"name":"other","timestamp":10,"value":9}
	]`)

	res := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 25))
	if len(res.Series) != 3 {
		t.Fatalf("series = %+v, want 3", res.Series)
	}
	// 与 organizeSeries 的次序一致：无标签在前，其次 host=h,zone=x，最后 zone=x。
	wantIdentity := []struct {
		labels map[string]string
		win    []Window
	}{
		{map[string]string{}, []Window{window(0, 24, 1, 1)}},
		{map[string]string{"host": "h", "zone": "x"}, []Window{window(0, 24, 1, 2)}},
		{map[string]string{"zone": "x"}, []Window{window(25, 49, 1, 3)}},
	}
	for i, wi := range wantIdentity {
		s := res.Series[i]
		if s.Name != "m" || !sameLabels(s.Labels, wi.labels) {
			t.Fatalf("series[%d] = %+v, want identity m%v", i, s, wi.labels)
		}
		assertWindows(t, s.Windows, wi.win, fmt.Sprintf("series[%d]", i))
	}
	// 标签副本独立：修改结果不影响存储，再次查询一致。
	res.Series[0].Labels["injected"] = "y"
	res2 := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 25))
	if _, ok := res2.Series[0].Labels["injected"]; ok {
		t.Fatalf("result labels must be an independent copy, got %v", res2.Series[0].Labels)
	}

	// 子集匹配 zone=x：两条序列，返回完整标签集合而不缩减成查询条件。
	res = mustQueryWindows(t, store, `{"op":"query_windows","name":"m","start":0,"end":100,"step":25,"labels":{"zone":"x"}}`)
	if len(res.Series) != 2 {
		t.Fatalf("subset match = %+v, want 2 series", res.Series)
	}
	if !sameLabels(res.Series[0].Labels, map[string]string{"host": "h", "zone": "x"}) ||
		!sameLabels(res.Series[1].Labels, map[string]string{"zone": "x"}) {
		t.Fatalf("full label sets must be preserved: %+v", res.Series)
	}
}

// TestQueryWindowsCountAndAverageRules count 只统计已成功保存的点（等值重复
// 不增加），平均值依据实际存储的 float64、按 query 的精确平均与居中取偶规则。
func TestQueryWindowsCountAndAverageRules(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":0,"value":1},
		{"name":"m","timestamp":1,"value":1.0000000000000002}
	]`)
	// 同值重复：count 不增加。
	mustOK(t, store, `[{"name":"m","timestamp":0,"value":1.0}]`)

	res := mustQueryWindows(t, store, queryWindowsAll("m", 0, 9, 10))
	// (1 + 1.0000000000000002)/2 恰居两者正中，取偶为 1；count=2（重复点不计）。
	assertWindows(t, res.Series[0].Windows,
		[]Window{window(0, 9, 2, 1)}, "nearest-even average over stored float64")

	// 每个窗口独立统计，窗口间不共享计数。
	mustOK(t, store, `[{"name":"m","timestamp":10,"value":10}]`)
	res = mustQueryWindows(t, store, queryWindowsAll("m", 0, 19, 10))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(0, 9, 2, 1),
		window(10, 19, 1, 10),
	}, "per-window independent counts")
}

// TestQueryWindowsLargeNumberCancellation 同一窗口内正负大数抵消后小余量保留，
// 且窗口内总和超出 float64 范围时平均仍有限——与 query 相同的精确有理数求和。
func TestQueryWindowsLargeNumberCancellation(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"x","timestamp":0,"value":1e16},
		{"name":"x","timestamp":1,"value":1},
		{"name":"x","timestamp":2,"value":-1e16},
		{"name":"x","timestamp":10,"value":1e308},
		{"name":"x","timestamp":11,"value":1e308}
	]`)
	res := mustQueryWindows(t, store, queryWindowsAll("x", 0, 19, 10))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(0, 9, 3, 1.0/3.0), // big-rat 1/3 → nearest float64
		window(10, 19, 2, 1e308), // sum 2e308 overflows float64, mean stays finite
	}, "exact per-window arithmetic")
	if math.IsInf(res.Series[0].Windows[1].Average, 0) || math.IsNaN(res.Series[0].Windows[1].Average) {
		t.Fatalf("average must stay finite, got %v", res.Series[0].Windows[1].Average)
	}

	// 与同数据的整段 query 结果对照：query 同样精确求和，均值有限。
	qr := mustQuery(t, store, `{"op":"query","name":"x","start":0,"end":19}`)
	if len(qr.Series) != 1 || qr.Series[0].Count != 5 {
		t.Fatalf("query over same range = %+v, want count 5", qr.Series)
	}
	if math.IsInf(qr.Series[0].Average, 0) {
		t.Fatalf("query average must be finite, got inf")
	}
}

// TestQueryWindowsInt64Boundaries 起止时间与 step 接近 int64 上下界时窗口不
// 溢出、不倒置、不遗漏采样：覆盖跨整个 int64 区间、step 为 MaxInt64、
// start 为 MinInt64 等组合。
func TestQueryWindowsInt64Boundaries(t *testing.T) {
	min := tsMinInt64
	max := tsMaxInt64

	// 四个采样：MinInt64、-2、-1、MaxInt64；区间为整个 int64，step=MaxInt64。
	store := NewMetricStore()
	mustOK(t, store, "["+
		sample("m", min, 3, nil)+","+
		sample("m", -2, 9, nil)+","+
		sample("m", -1, 1, nil)+","+
		sample("m", max, 5, nil)+"]")
	res := mustQueryWindows(t, store, queryWindowsAll("m", min, max, max))
	// 窗口 0：[MinInt64, MinInt64+MaxInt64-1] = [MinInt64, -2]
	// 窗口 1：[-1, -1+MaxInt64-1] = [-1, MaxInt64-2]
	// 窗口 2：[MaxInt64-1, MaxInt64]（截到 end）
	assertWindows(t, res.Series[0].Windows, []Window{
		window(min, -2, 2, 6),
		window(-1, max-2, 1, 1),
		window(max-1, max, 1, 5),
	}, "full int64 range, step MaxInt64, no overflow/inversion")

	// step=1：每个时间戳独立窗口，首尾窗口的边界都精确。
	res = mustQueryWindows(t, store, queryWindowsAll("m", min, max, 1))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(min, min, 1, 3),
		window(-2, -2, 1, 9),
		window(-1, -1, 1, 1),
		window(max, max, 1, 5),
	}, "step 1 across full int64 range")

	// 负起点附近的小步划分：[-5,4]、step=3 → [-5,-3]、[-2,0]、[1,3]、[4,4]。
	store2 := NewMetricStore()
	for ts, v := range map[int64]float64{-5: 1, -3: 3, -2: 5, 0: 9, 1: 7, 3: 1, 4: 2} {
		mustOK(t, store2, "["+sample("m", ts, v, nil)+"]")
	}
	res = mustQueryWindows(t, store2, queryWindowsAll("m", -5, 4, 3))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(-5, -3, 2, 2),
		window(-2, 0, 2, 7),
		window(1, 3, 2, 4),
		window(4, 4, 1, 2),
	}, "negative start tiled without overflow")

	// start 为 MinInt64、end 为 -1（全负半区），step=MaxInt64：第一个窗口的
	// 自然终点 -2 未越过 end，保持完整宽度；第二个窗口从 -1 开始，截到 end=-1。
	res = mustQueryWindows(t, store, queryWindowsAll("m", min, -1, max))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(min, -2, 2, 6),
		window(-1, -1, 1, 1),
	}, "negative half, huge step clips second window to end")
}

// TestQueryWindowsStepValidation step 必须是大于零、int64 范围内的 JSON 整数；
// 缺失、类型不符、值不合法都返回指出 step 的查询错误。
func TestQueryWindowsStepValidation(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2}]`)

	cases := []struct {
		name string
		line string
		want string
	}{
		{"missing step", `{"op":"query_windows","name":"cpu","start":0,"end":1}`, `missing required field "step"`},
		{"step zero", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":0}`, `field "step"`},
		{"step negative", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":-1}`, `field "step"`},
		{"step string", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":"1"}`, `field "step" must be a JSON number`},
		{"step boolean", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":true}`, `field "step" must be a JSON number`},
		{"step null", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":null}`, `field "step" must be a JSON number`},
		{"step float", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":1.5}`, `field "step"`},
		{"step exponent fraction", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":1e0}`, `field "step"`},
		{"step over int64", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":9223372036854775808}`, `field "step"`},
		{"step under int64", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":-9223372036854775809}`, `field "step"`},
		{"step object", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":{}}`, `field "step" must be a JSON number`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lerr := mustQueryWindowsFail(t, store, tc.line)
			assertQueryError(t, lerr, tc.want)
			// 失败结果没有 series、index 或 conflict。
			m := marshalLineError(t, lerr)
			for _, banned := range []string{"series", "index", "conflict"} {
				if _, ok := m[banned]; ok {
					t.Fatalf("query_windows failure must not carry %q: %v", banned, m)
				}
			}
		})
	}

	// 合法 step 恰好为 int64 上界：成功。
	res := mustQueryWindows(t, store, queryWindowsAll("cpu", 0, tsMaxInt64, tsMaxInt64))
	if res.Op != "query_windows" {
		t.Fatalf("step MaxInt64 must be accepted, got %+v", res)
	}
}

// TestQueryWindowsStepOnlyForNewOp step 只用于 query_windows：query 与
// query_points 携带 step 一律按未知字段拒绝；query_windows 仍可省略 labels。
func TestQueryWindowsStepOnlyForNewOp(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2}]`)

	// step 写在 op 之后：读到 step 立即按未知字段拒绝。
	lerr := mustQueryFail(t, store, `{"op":"query","name":"cpu","start":0,"end":2000,"step":1000}`)
	assertQueryError(t, lerr, `unknown field "step"`)
	lerr = mustQueryPointsFail(t, store, `{"op":"query_points","name":"cpu","start":0,"end":2000,"step":1000}`)
	assertQueryError(t, lerr, `unknown field "step"`)

	// step 写在 op 之前：读完对象再判未知字段，且该判定先于缺字段/区间检查。
	lerr = mustQueryFail(t, store, `{"step":1000,"op":"query","name":"cpu","start":0,"end":2000}`)
	assertQueryError(t, lerr, `unknown field "step"`)

	// step 写在 op 之前时，值是否合法不影响未知字段判定：零、字符串、对象
	// 都按未知字段拒绝，绝不退化成窗口宽度校验。
	for _, line := range []string{
		`{"step":0,"op":"query","name":"cpu","start":0,"end":2000}`,
		`{"step":"1000","op":"query","name":"cpu","start":0,"end":2000}`,
		`{"step":{},"op":"query","name":"cpu","start":0,"end":2000}`,
		`{"step":0,"op":"query_points","name":"cpu","start":0,"end":2000}`,
		`{"step":"1000","op":"query_points","name":"cpu","start":0,"end":2000}`,
		`{"step":{},"op":"query_points","name":"cpu","start":0,"end":2000}`,
	} {
		lerr = mustQueryFail(t, store, line)
		assertQueryError(t, lerr, `unknown field "step"`)
	}

	// 错误仍按字段书写次序选择：step 之前的字段错误先报；把错误字段移到
	// step 之后则先报 step，即使 op 写在它们之后也一样。
	lerr = mustQueryFail(t, store, `{"name":7,"step":1,"op":"query","start":0,"end":1}`)
	assertQueryError(t, lerr, `field "name" must be a string`)
	lerr = mustQueryFail(t, store, `{"step":1,"name":7,"op":"query","start":0,"end":1}`)
	assertQueryError(t, lerr, `unknown field "step"`)

	// step 的未知字段错误先于缺少必填项与区间倒置。
	lerr = mustQueryFail(t, store, `{"step":1,"op":"query"}`)
	assertQueryError(t, lerr, `unknown field "step"`)
	lerr = mustQueryFail(t, store, `{"step":1,"op":"query","name":"cpu","start":5,"end":1}`)
	assertQueryError(t, lerr, `unknown field "step"`)

	// 删掉 step 后原查询正常执行。
	qr := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":2000}`)
	if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 2 {
		t.Fatalf("query compatibility broken: %+v", qr.Series)
	}
	qp := mustQueryPoints(t, store, `{"op":"query_points","name":"cpu","start":0,"end":2000}`)
	if len(qp.Series) != 1 || len(qp.Series[0].Points) != 1 {
		t.Fatalf("query_points compatibility broken: %+v", qp.Series)
	}

	// op 缺失、类型错误、未知操作或重复出现时沿用既有处理：step 在出现处
	// 按窗口宽度校验，op 自身的问题按书写次序暴露。
	lerr = mustQueryFail(t, store, `{"step":0,"name":"cpu","start":0,"end":1}`)
	assertQueryError(t, lerr, `field "step"`)
	lerr = mustQueryFail(t, store, `{"step":0,"op":5,"name":"cpu","start":0,"end":1}`)
	assertQueryError(t, lerr, `field "step"`)
	lerr = mustQueryFail(t, store, `{"step":0,"op":"ping","name":"cpu","start":0,"end":1}`)
	assertQueryError(t, lerr, `field "step"`)
	lerr = mustQueryFail(t, store, `{"step":5,"op":"query","op":"query","name":"cpu","start":0,"end":1}`)
	assertQueryError(t, lerr, `duplicate field "op"`)
}

// TestQueryWindowsErrorSelection 失败原因的选择沿用查询对象的既有次序：
// 整行解析失败最先；已出现字段按书写顺序；缺字段在已出现字段合法之后；
// query_windows 特有“缺 step”排在四项必填之后、倒置区间之前。
func TestQueryWindowsErrorSelection(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2}]`)

	// 倒置区间 + 缺 step：四项必填齐全后先报缺 step（区间检查在最后）。
	lerr := mustQueryWindowsFail(t, store, `{"op":"query_windows","name":"cpu","start":5,"end":1}`)
	assertQueryError(t, lerr, `missing required field "step"`)

	// 倒置区间 + step 合法：才报区间倒置并给出实际边界。
	lerr = mustQueryWindowsFail(t, store, `{"op":"query_windows","name":"cpu","start":5,"end":1,"step":2}`)
	assertQueryError(t, lerr, `invalid range: "start" must not be greater than "end" (5 > 1)`)

	// 倒置区间 + 未知字段：先报未知字段（书写顺序）。
	lerr = mustQueryWindowsFail(t, store, `{"op":"query_windows","name":"cpu","start":5,"end":1,"step":2,"bogus":1}`)
	assertQueryError(t, lerr, `unknown field "bogus"`)

	// step 非法 + 倒置区间：step 字段问题先于区间检查。
	lerr = mustQueryWindowsFail(t, store, `{"op":"query_windows","name":"cpu","start":5,"end":1,"step":0}`)
	assertQueryError(t, lerr, `field "step"`)

	// 缺多项必填：仍按 op、name、start、end 的顺序；四项齐了才轮到 step。
	for _, tc := range []struct {
		line string
		want string
	}{
		{`{"start":0,"end":1,"step":1}`, `missing required field "op"`},
		{`{"op":"query_windows","start":0,"end":1,"step":1}`, `missing required field "name"`},
		{`{"op":"query_windows","name":"cpu","end":1,"step":1}`, `missing required field "start"`},
		{`{"op":"query_windows","name":"cpu","start":0,"step":1}`, `missing required field "end"`},
	} {
		lerr = mustQueryWindowsFail(t, store, tc.line)
		assertQueryError(t, lerr, tc.want)
	}

	// 未知 op：措辞覆盖三种操作。
	lerr = mustQueryWindowsFail(t, store, `{"op":"ping","name":"cpu","start":0,"end":1,"step":1}`)
	assertQueryError(t, lerr, `unknown op "ping"`)
	assertQueryError(t, lerr, "query_windows")

	// 整行解析失败最先（对象未闭合，即使字段类型已错）。
	lerr = mustQueryWindowsFail(t, store, `{"op":"query_windows","name":7,"step":1`)
	assertQueryError(t, lerr, "invalid JSON")
}

// TestQueryWindowsViaProcessLine 统一入口按 op 分派到 *QueryWindowsResult；
// 三个专用入口交叉使用时各自拒绝不属于自己的 op，且不返回另一类型的结果。
func TestQueryWindowsViaProcessLine(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2}]`)
	line := `{"op":"query_windows","name":"cpu","start":0,"end":2000,"step":1000}`

	r, lerr := store.ProcessLine(line)
	if lerr != nil || r == nil {
		t.Fatalf("ProcessLine query_windows: r=%v lerr=%+v", r, lerr)
	}
	qw, ok := r.(*QueryWindowsResult)
	if !ok {
		t.Fatalf("ProcessLine result type = %T, want *QueryWindowsResult", r)
	}
	if qw.Op != "query_windows" || len(qw.Series) != 1 {
		t.Fatalf("ProcessLine query_windows = %+v", qw)
	}

	// 倒置区间经统一入口失败：真正的 nil 结果。
	r, lerr = store.ProcessLine(`{"op":"query_windows","name":"cpu","start":9,"end":1,"step":2}`)
	if r != nil || lerr == nil || !strings.Contains(lerr.Error, "9 > 1") {
		t.Fatalf("inverted query_windows via ProcessLine: r=%v lerr=%+v", r, lerr)
	}

	// 专用入口交叉使用：各报各的引导信息，不串结果类型。
	if _, lerr = store.QueryLine(line); lerr == nil || !strings.Contains(lerr.Error, "query_windows") {
		t.Fatalf("QueryLine must reject query_windows, got %+v", lerr)
	}
	if _, lerr = store.QueryPointsLine(line); lerr == nil || !strings.Contains(lerr.Error, "query_windows") {
		t.Fatalf("QueryPointsLine must reject query_windows, got %+v", lerr)
	}
	if _, lerr = store.QueryWindowsLine(`{"op":"query","name":"cpu","start":0,"end":1}`); lerr == nil {
		t.Fatalf("QueryWindowsLine must reject op query")
	}
	if _, lerr = store.QueryWindowsLine(`{"op":"query_points","name":"cpu","start":0,"end":1}`); lerr == nil {
		t.Fatalf("QueryWindowsLine must reject op query_points")
	}
}

// TestQueryWindowsReadOnlyAndCommittedOnly query_windows 只读取此前成功提交的
// 数据：失败批次回滚的点不可见、等值重复不计入；查询不改变存储，与写入、
// query、query_points 交替进行互不影响。
func TestQueryWindowsReadOnlyAndCommittedOnly(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"m","timestamp":10,"value":2}]`)
	mustOK(t, store, `[{"name":"m","timestamp":20,"value":4}]`)

	baseline := func() {
		t.Helper()
		res := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 50))
		want := []Window{window(0, 49, 2, 3)}
		if len(res.Series) != 1 {
			t.Fatalf("baseline series = %+v, want one", res.Series)
		}
		assertWindows(t, res.Series[0].Windows, want, "baseline")
	}
	baseline()

	// 失败批次整批回滚，窗口统计看不到其中任何点。
	mustFail(t, store, `[{"name":"m","timestamp":30,"value":8},{"name":"m","timestamp":10,"value":100}]`)
	baseline()

	// 等值重复不改变 count。
	mustOK(t, store, `[{"name":"m","timestamp":20,"value":4.0}]`)
	baseline()

	// 重复查询结果一致。
	r1 := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 50))
	r2 := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 50))
	if !reflect.DeepEqual(r1, r2) {
		t.Fatalf("repeated query_windows differs: %+v vs %+v", r1, r2)
	}

	// 存储未被改变：快照与另两种查询保持原状。
	snap := mustOK(t, store, `[]`)
	if len(snap.Series) != 1 || len(snap.Series[0].Points) != 2 {
		t.Fatalf("query_windows mutated storage, snapshot = %+v", snap.Series)
	}
	qr := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100}`)
	if qr.Series[0].Count != 2 || qr.Series[0].Average != 3 {
		t.Fatalf("query after query_windows = %+v", qr.Series)
	}

	// 后续写入可见：窗口统计随之增长。
	mustOK(t, store, `[{"name":"m","timestamp":60,"value":9}]`)
	res := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 50))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(0, 49, 2, 3),
		window(50, 99, 1, 9),
	}, "newly committed point appears in its window")
}

// TestQueryWindowsMultipleSeriesShareBoundaries 各序列共用同一组由 start 与
// step 决定的边界：不同序列的点在相同时间戳上归入相同窗口，输出窗口的
// start/end 一致；序列各自只列自己非空的窗口。
func TestQueryWindowsMultipleSeriesShareBoundaries(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":5,"value":1,"labels":{"h":"a"}},
		{"name":"m","timestamp":25,"value":3,"labels":{"h":"a"}},
		{"name":"m","timestamp":15,"value":7,"labels":{"h":"b"}}
	]`)
	res := mustQueryWindows(t, store, queryWindowsAll("m", 0, 39, 20))
	if len(res.Series) != 2 {
		t.Fatalf("series = %+v, want 2", res.Series)
	}
	// h=a 有点的窗口 0 与窗口 1；h=b 只有窗口 0——边界 [0,19]/[20,39] 相同。
	assertWindows(t, res.Series[0].Windows, []Window{
		window(0, 19, 1, 1),
		window(20, 39, 1, 3),
	}, "h=a windows")
	assertWindows(t, res.Series[1].Windows, []Window{
		window(0, 19, 1, 7),
	}, "h=b windows")
}

package darksafe

import (
	"encoding/json"
	"fmt"
	"math/big"
	"reflect"
	"sort"
	"strings"
	"testing"
)

// 本文件回归保障固定时间窗口统计与采样明细描述的是同一组采样：用户在同一份
// 已成功写入的数据上，用相同的指标名、标签条件和起止时间分别发送 op 为
// "query_windows"（额外给出合法 step）与 "query_points" 的查询，两种结果
// 必须能逐条核对：
//
//   - 两种结果的序列身份（指标名+完整标签集合）与排列次序完全一致；标签条件
//     只筛选序列，返回的记录仍携带完整标签集合，不缩减成查询条件；
//   - 同名但完整标签不同的序列各自统计，即使采样时间戳完全相同也不合并；
//   - 窗口从查询起点 start 起按 step 连续划分（第 k 个窗口为
//     [start+k*step, start+(k+1)*step-1]，最后一个截到 end），不跟随各序列
//     的第一个采样点移动；不同序列可以缺少不同窗口，只有实际有点的窗口出现，
//     按窗口起点升序；
//   - 对每个返回窗口，count 等于该序列明细中落在窗口闭区间内的点数，average
//     等于这些点实际存储值的算术平均——测试侧从 query_points 明细出发，用
//     big.Int/big.Rat 独立重算窗口归属、边界与均值（不经过生产代码的窗口
//     划分与舍入实现），保证统计侧与复核侧不共用同一份可能出错的逻辑；
//   - 整段明细中的每个点恰好计入一个窗口：既不遗漏，也不在相邻窗口重复计数；
//   - 没有区间内采样的序列在两边都不出现；完全未命中时两边都成功返回空数组。
//
// 失败信息一律指出查询区间、step、完整序列身份与出问题的窗口，说明是点数、
// 采样归属还是均值不符，便于定位后续修改造成的窗口统计偏差。

// windowPair 是除 op 与 step 外条件完全相同的一对查询文本：用户复核时只把
// op 从 query_points 换成 query_windows 并补上 step，其余条件（指标名、
// 标签条件、起止时间）逐字保持相同。
type windowPair struct {
	note    string // 区间/场景的人类可读说明
	windows string // op 为 "query_windows"，带 step
	points  string // op 为 "query_points"
	start   int64  // 用于失败信息指明是哪个区间，并独立重算窗口归属
	end     int64
	step    int64
}

// windowPairsFor 用同一组条件构造一对查询文本。labels 为 nil 时省略 labels
// 字段（匹配该指标全部序列）；非 nil 时显式带 labels（空 map 即 {}）。
func windowPairsFor(name string, start, end, step int64, labels map[string]string) windowPair {
	note := fmt.Sprintf("metric=%q range=[%d,%d] step=%d", name, start, end, step)
	if labels == nil {
		return windowPair{
			note:    note + " labels=<omit>",
			windows: queryWindowsAll(name, start, end, step),
			points:  queryPointsAll(name, start, end),
			start:   start,
			end:     end,
			step:    step,
		}
	}
	return windowPair{
		note:    note + " labels=" + jsonLabels(labels),
		windows: queryWindowsLabels(name, start, end, step, labels),
		points:  queryPointsLabels(name, start, end, labels),
		start:   start,
		end:     end,
		step:    step,
	}
}

// windowExpect 是从明细独立重算出的一个应出现的窗口：闭区间边界与落入其中的
// 明细点（按明细原有次序）。
type windowExpect struct {
	start  int64
	end    int64
	points []Point
}

// expectWindowsFromDetail 从 query_points 明细独立重算应出现的窗口列表：
// 每个点的窗口下标为 floor((ts-start)/step)，窗口边界为
// [start+idx*step, min(start+(idx+1)*step-1, end)]。全部用 big.Int 运算，
// 不调用生产代码的窗口划分（runQueryWindows/buildWindow/int64AtOffset），
// 因此即使起止时间接近 int64 上下界、step 接近 int64 上界，复核侧也不会
// 与统计侧共享同一个溢出或划分错误。points 必须全部落在 [start,end] 内
// （调用方已校验），因此下标非负，Quo 即向下取整。返回按窗口起点升序。
func expectWindowsFromDetail(t *testing.T, points []Point, start, end, step int64) []windowExpect {
	t.Helper()
	bigStart := big.NewInt(start)
	bigStep := big.NewInt(step)
	bigEnd := big.NewInt(end)
	one := big.NewInt(1)

	byIdx := make(map[string][]Point)
	seen := make(map[string]*big.Int)
	var idxs []*big.Int
	for _, p := range points {
		idx := new(big.Int).Sub(big.NewInt(p.Timestamp), bigStart)
		idx.Quo(idx, bigStep)
		key := idx.String()
		if _, ok := seen[key]; !ok {
			seen[key] = idx
			idxs = append(idxs, idx)
		}
		byIdx[key] = append(byIdx[key], p)
	}
	sort.Slice(idxs, func(i, j int) bool { return idxs[i].Cmp(idxs[j]) < 0 })

	out := make([]windowExpect, 0, len(idxs))
	for _, idx := range idxs {
		ws := new(big.Int).Add(bigStart, new(big.Int).Mul(idx, bigStep))
		we := new(big.Int).Sub(new(big.Int).Add(ws, bigStep), one)
		if we.Cmp(bigEnd) > 0 {
			we.Set(bigEnd)
		}
		if !ws.IsInt64() || !we.IsInt64() {
			t.Fatalf("internal: recomputed window bounds out of int64: [%s,%s]", ws, we)
		}
		out = append(out, windowExpect{
			start:  ws.Int64(),
			end:    we.Int64(),
			points: byIdx[idx.String()],
		})
	}
	return out
}

// windowsIdentitySigs 在序列数量不一致的失败信息中列出窗口结果全部序列身份。
func windowsIdentitySigs(xs []QueryWindowsSeries) string {
	parts := make([]string, len(xs))
	for i, x := range xs {
		parts[i] = identitySig(x.Name, x.Labels)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

// assertWindowPointsCorrespond 对同一区间执行一对查询（query_windows 与
// query_points，其余条件相同），断言两种结果描述同一组采样：
//   - 双方都成功，status/op 正确；
//   - 序列身份（name+完整标签）与排列次序逐一相同，两侧标签集合相同；
//   - 明细点时间戳严格升序、两两不同，且都落在闭区间 [start,end] 内；
//   - 返回的窗口与从明细独立重算的窗口逐一相同：边界、count（窗口闭区间内
//     明细点数）、average（这些点实际存储值的精确平均，最近偶 float64）；
//   - 窗口按起点升序、不含空窗口；每个明细点恰好计入一个窗口（计数总和
//     等于明细点数，既不遗漏也不在相邻窗口重复）；
//   - 两侧都不出现没有点的空记录；空结果是成功的非 nil 空数组。
//
// 每个失败信息都带查询区间、step 与序列身份签名，窗口级失败再指出具体窗口。
func assertWindowPointsCorrespond(t *testing.T, store *MetricStore, p windowPair) {
	t.Helper()
	win := mustQueryWindows(t, store, p.windows)
	det := mustQueryPoints(t, store, p.points)
	if win.Status != "ok" || win.Op != "query_windows" {
		t.Fatalf("[%d,%d] step=%d %s: windows envelope = %q/%q, want ok/query_windows",
			p.start, p.end, p.step, p.note, win.Status, win.Op)
	}
	if det.Status != "ok" || det.Op != "query_points" {
		t.Fatalf("[%d,%d] step=%d %s: detail envelope = %q/%q, want ok/query_points",
			p.start, p.end, p.step, p.note, det.Status, det.Op)
	}

	// 序列数量、身份与排列次序逐一相同。
	if len(win.Series) != len(det.Series) {
		t.Fatalf("[%d,%d] step=%d %s: query_windows returned %d series but query_points returned %d:\nwindows: %s\ndetail:  %s",
			p.start, p.end, p.step, p.note, len(win.Series), len(det.Series),
			windowsIdentitySigs(win.Series), detailIdentitySigs(det.Series))
	}
	for i := range win.Series {
		sigW := identitySig(win.Series[i].Name, win.Series[i].Labels)
		sigD := identitySig(det.Series[i].Name, det.Series[i].Labels)
		if sigW != sigD {
			t.Fatalf("[%d,%d] step=%d %s: series[%d] identity/order mismatch:\nquery_windows #%d = %s\nquery_points  #%d = %s",
				p.start, p.end, p.step, p.note, i, i, sigW, i, sigD)
		}
	}

	// 逐条序列核对窗口统计与明细的对应关系。
	for i := range win.Series {
		ws := win.Series[i]
		ds := det.Series[i]
		sig := identitySig(ws.Name, ws.Labels)

		// 两种结果携带的标签集合必须相同（且为完整集合，由各场景另行核对）。
		if !sameLabels(ws.Labels, ds.Labels) {
			t.Fatalf("[%d,%d] step=%d %s: %s: labels differ between results: windows=%v detail=%v",
				p.start, p.end, p.step, p.note, sig, ws.Labels, ds.Labels)
		}
		// 没有点的序列不能被任一侧补成空记录。
		if len(ds.Points) == 0 {
			t.Fatalf("[%d,%d] step=%d %s: %s: zero-point entry must not be emitted by either query",
				p.start, p.end, p.step, p.note, sig)
		}

		// 明细按时间戳严格升序，且每个点都在闭区间内。
		for j, pt := range ds.Points {
			if pt.Timestamp < p.start || pt.Timestamp > p.end {
				t.Fatalf("[%d,%d] step=%d %s: %s: detail point[%d] ts=%d is outside the closed range",
					p.start, p.end, p.step, p.note, sig, j, pt.Timestamp)
			}
			if j > 0 && ds.Points[j-1].Timestamp >= pt.Timestamp {
				t.Fatalf("[%d,%d] step=%d %s: %s: detail not strictly ascending at %d: %+v",
					p.start, p.end, p.step, p.note, sig, j, ds.Points)
			}
		}

		// 从明细独立重算应出现的窗口，与返回窗口逐一比对。
		want := expectWindowsFromDetail(t, ds.Points, p.start, p.end, p.step)
		got := ws.Windows
		if len(got) != len(want) {
			t.Fatalf("[%d,%d] step=%d %s: %s: returned %d windows %+v, but the detail implies %d non-empty windows %+v",
				p.start, p.end, p.step, p.note, sig, len(got), got, len(want), want)
		}
		total := 0
		for k := range got {
			g := got[k]
			w := want[k]
			wsig := fmt.Sprintf("window [%d,%d]", w.start, w.end)
			if k > 0 && got[k-1].Start >= g.Start {
				t.Fatalf("[%d,%d] step=%d %s: %s: windows not ascending by start at %d: %+v",
					p.start, p.end, p.step, p.note, sig, k, got)
			}
			if g.Start != w.start || g.End != w.end {
				t.Fatalf("[%d,%d] step=%d %s: %s: %s: returned bounds [%d,%d], window tiling from the query start is off",
					p.start, p.end, p.step, p.note, sig, wsig, g.Start, g.End)
			}
			if g.Count != len(w.points) {
				t.Fatalf("[%d,%d] step=%d %s: %s: %s: count=%d but %d detail points fall inside: %+v",
					p.start, p.end, p.step, p.note, sig, wsig, g.Count, len(w.points), w.points)
			}
			if g.Count == 0 {
				t.Fatalf("[%d,%d] step=%d %s: %s: %s: empty window must not be emitted",
					p.start, p.end, p.step, p.note, sig, wsig)
			}
			wantAvg := detailMean(t, w.points)
			if g.Average != wantAvg {
				t.Fatalf("[%d,%d] step=%d %s: %s: %s: average=%v but recomputed from the detail points in this window = %v (points=%+v)",
					p.start, p.end, p.step, p.note, sig, wsig, g.Average, wantAvg, w.points)
			}
			total += g.Count
		}
		// 划分性：每个明细点恰好计入一个窗口——计数总和等于明细点数，
		// 既不遗漏，也不在相邻窗口重复计数。
		if total != len(ds.Points) {
			t.Fatalf("[%d,%d] step=%d %s: %s: window counts sum to %d but the detail lists %d points; every point must be counted in exactly one window",
				p.start, p.end, p.step, p.note, sig, total, len(ds.Points))
		}
	}
}

// TestWindowsPointsSpecBoundariesCorrespond 任务书指定的窗口划分：查询
// [1000,3000]、step 1000 时边界是 [1000,1999]、[2000,2999]、[3000,3000]——
// 1999 与 2000 上的点分属相邻窗口，3000 上的点归入最后一个窗口。逐窗口与
// query_points 明细核对点数与均值。
func TestWindowsPointsSpecBoundariesCorrespond(t *testing.T) {
	store := NewMetricStore()
	labelsA := map[string]string{"host": "a"}
	mustOK(t, store, "["+
		sample("cpu", 500, 77, labelsA)+","+ // 区间下方之外
		sample("cpu", 1000, 2, labelsA)+","+
		sample("cpu", 1999, 4, labelsA)+","+ // 第一个窗口的最后一毫秒
		sample("cpu", 2000, 6, labelsA)+","+ // 第二个窗口的第一毫秒
		sample("cpu", 2999, 8, labelsA)+","+ // 第二个窗口的最后一毫秒
		sample("cpu", 3000, 10, labelsA)+","+ // 收尾窗口 [3000,3000]
		sample("cpu", 4000, 88, labelsA)+"]") // 区间上方之外

	pair := windowPairsFor("cpu", 1000, 3000, 1000, labelsA)
	assertWindowPointsCorrespond(t, store, pair)

	// 明细侧：恰好区间内 5 个点，按时间升序，区间外的 500/4000 不出现。
	det := mustQueryPoints(t, store, pair.points)
	if len(det.Series) != 1 {
		t.Fatalf("[1000,3000] host=a: detail series = %s, want exactly 1",
			detailIdentitySigs(det.Series))
	}
	wantPoints := []Point{
		{Timestamp: 1000, Value: 2},
		{Timestamp: 1999, Value: 4},
		{Timestamp: 2000, Value: 6},
		{Timestamp: 2999, Value: 8},
		{Timestamp: 3000, Value: 10},
	}
	if !reflect.DeepEqual(det.Series[0].Points, wantPoints) {
		t.Fatalf("[1000,3000] %s: detail points = %+v, want %+v",
			identitySig("cpu", labelsA), det.Series[0].Points, wantPoints)
	}

	// 窗口侧：三个窗口的边界、点数、均值与明细逐条对应。
	win := mustQueryWindows(t, store, pair.windows)
	if len(win.Series) != 1 {
		t.Fatalf("[1000,3000] host=a: windows series = %s, want exactly 1",
			windowsIdentitySigs(win.Series))
	}
	assertWindows(t, win.Series[0].Windows, []Window{
		window(1000, 1999, 2, 3), // 1000 与 1999
		window(2000, 2999, 2, 7), // 2000 与 2999
		window(3000, 3000, 1, 10),
	}, "spec tiling [1000,3000] step 1000")
}

// TestWindowsPointsAnchoredAtQueryStart 窗口从查询起点划分，不跟随各序列的
// 第一个采样点移动：同一组采样在不同查询起点下入窗不同；序列第一个采样点
// 之前可以有空窗口（不补零），窗口起点始终是 start+k*step。
func TestWindowsPointsAnchoredAtQueryStart(t *testing.T) {
	store := NewMetricStore()
	// 第一个采样点在 1500，刻意不在任何窗口边界上。
	mustOK(t, store, "["+
		sample("m", 1500, 2, nil)+","+
		sample("m", 1600, 4, nil)+","+
		sample("m", 2500, 6, nil)+"]")

	// 查询 [1000,3000]、step 1000：窗口从 1000 起划分，不是从 1500 起；
	// 1500/1600 同入 [1000,1999]，2500 入 [2000,2999]。
	pair := windowPairsFor("m", 1000, 3000, 1000, nil)
	assertWindowPointsCorrespond(t, store, pair)
	win := mustQueryWindows(t, store, pair.windows)
	assertWindows(t, win.Series[0].Windows, []Window{
		window(1000, 1999, 2, 3),
		window(2000, 2999, 1, 6),
	}, "windows anchored at query start 1000, not at first sample 1500")

	// 同一组采样、查询起点改为 1200：边界整体平移，1500 入 [1200,2199]，
	// 1600 仍与 1500 同窗，2500 入 [2200,3000]（截到 end）。
	pair2 := windowPairsFor("m", 1200, 3000, 1000, nil)
	assertWindowPointsCorrespond(t, store, pair2)
	win2 := mustQueryWindows(t, store, pair2.windows)
	assertWindows(t, win2.Series[0].Windows, []Window{
		window(1200, 2199, 2, 3),
		window(2200, 3000, 1, 6),
	}, "same samples re-tiled when the query start moves to 1200")

	// 起点对齐到采样点本身：1500 成为窗口起点。
	pair3 := windowPairsFor("m", 1500, 3000, 1000, nil)
	assertWindowPointsCorrespond(t, store, pair3)
	win3 := mustQueryWindows(t, store, pair3.windows)
	assertWindows(t, win3.Series[0].Windows, []Window{
		window(1500, 2499, 2, 3),
		window(2500, 3000, 1, 6),
	}, "start aligned with the first sample")
}

// TestWindowsPointsMultiSeriesIndependent 同名但完整标签不同的序列各自统计：
// 即使采样时间戳完全相同也不合并；标签条件只筛选序列，结果仍保留完整标签
// 集合；两种结果的序列次序一致；不同序列可以缺少不同窗口。
func TestWindowsPointsMultiSeriesIndependent(t *testing.T) {
	store := NewMetricStore()
	labelsA := map[string]string{"host": "a"}
	labelsB := map[string]string{"host": "b"}
	labelsCX := map[string]string{"dc": "1", "host": "c"}
	mustOK(t, store, "["+
		// host=a 与 host=b 在完全相同的时间戳上采样，值刻意不同：
		// 一旦合并统计，两条序列的 count/average 都会变。
		sample("m", 10, 2, labelsA)+","+
		sample("m", 20, 4, labelsA)+","+
		sample("m", 10, 200, labelsB)+","+
		sample("m", 20, 400, labelsB)+","+
		sample("m", 35, 7, labelsCX)+","+ // 只在窗口 [30,39] 有点
		sample("m", 45, 9, labelsB)+"]") // host=b 独有的窗口 [40,49]

	// 省略 labels：三条序列都返回，次序两侧一致。规范次序按排序后标签键值对
	// 逐对比较：{dc:1,host:c} 的首对键 dc 排在 host 之前，因此 host=c 在最前。
	pair := windowPairsFor("m", 0, 49, 10, nil)
	assertWindowPointsCorrespond(t, store, pair)
	win := mustQueryWindows(t, store, pair.windows)
	det := mustQueryPoints(t, store, pair.points)
	if len(win.Series) != 3 || len(det.Series) != 3 {
		t.Fatalf("[0,49] all-labels: series count windows=%d detail=%d, want 3",
			len(win.Series), len(det.Series))
	}
	wantOrder := []map[string]string{labelsCX, labelsA, labelsB}
	for i, want := range wantOrder {
		if !sameLabels(win.Series[i].Labels, want) || !sameLabels(det.Series[i].Labels, want) {
			t.Fatalf("[0,49] series[%d] identity = %v / %v, want full set %v",
				i, win.Series[i].Labels, det.Series[i].Labels, want)
		}
	}
	// host=c：只在自己有点的窗口出现，完整标签集合（含 dc）保留。
	assertWindows(t, win.Series[0].Windows, []Window{
		window(30, 39, 1, 7),
	}, "host=c appears only in its own window")
	// host=a：两个窗口各一点，统计不受同时间戳的 host=b 影响。
	assertWindows(t, win.Series[1].Windows, []Window{
		window(10, 19, 1, 2),
		window(20, 29, 1, 4),
	}, "host=a counted separately despite identical timestamps")
	// host=b：三个窗口（独有 [40,49]），均值是自己的大值。
	assertWindows(t, win.Series[2].Windows, []Window{
		window(10, 19, 1, 200),
		window(20, 29, 1, 400),
		window(40, 49, 1, 9),
	}, "host=b has its own windows, including the one host=a lacks")

	// 标签子集 host=c：只筛选序列，结果仍带完整标签 {"dc":"1","host":"c"}。
	sub := windowPairsFor("m", 0, 49, 10, map[string]string{"host": "c"})
	assertWindowPointsCorrespond(t, store, sub)
	subWin := mustQueryWindows(t, store, sub.windows)
	if len(subWin.Series) != 1 || !sameLabels(subWin.Series[0].Labels, labelsCX) {
		t.Fatalf("subset host=c = %+v, want the single series with its full label set %v",
			subWin.Series, labelsCX)
	}
}

// TestWindowsPointsCancellationWithinOneWindow 同一窗口内的 1e16、1、-1e16
// 保留抵消后的余量：均值为 0.3333333333333333；其他窗口中的点不能影响它——
// 切换窗口后点数与均值都只反映新窗口自己的采样。
func TestWindowsPointsCancellationWithinOneWindow(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, "["+
		sample("cpu", 1000, 1e16, nil)+","+
		sample("cpu", 1500, 1, nil)+","+
		sample("cpu", 1999, -1e16, nil)+","+
		// 相邻窗口的点：若泄漏进上一窗口，点数与均值都会变。
		sample("cpu", 2000, 1e308, nil)+","+
		sample("cpu", 2500, 1e308, nil)+"]")

	pair := windowPairsFor("cpu", 1000, 2999, 1000, nil)
	assertWindowPointsCorrespond(t, store, pair)
	win := mustQueryWindows(t, store, pair.windows)
	if len(win.Series) != 1 || len(win.Series[0].Windows) != 2 {
		t.Fatalf("windows = %+v, want one series with two windows", win.Series)
	}
	w0 := win.Series[0].Windows[0]
	if w0.Count != 3 || w0.Average != 1.0/3.0 {
		t.Fatalf("[1000,2999] step=1000 %s: window [1000,1999] = %+v, want count=3 average=1/3; the middle 1 must survive cancellation",
			identitySig("cpu", nil), w0)
	}
	b, _ := json.Marshal(w0.Average)
	if string(b) != "0.3333333333333333" {
		t.Fatalf("[1000,2999] step=1000 %s: window [1000,1999] average JSON = %s, want 0.3333333333333333",
			identitySig("cpu", nil), b)
	}
	// 第二个窗口只反映自己的两个 1e308：总和超出 float64 范围，均值仍有限。
	w1 := win.Series[0].Windows[1]
	if w1.Start != 2000 || w1.End != 2999 || w1.Count != 2 || w1.Average != 1e308 {
		t.Fatalf("[1000,2999] step=1000 %s: window [2000,2999] = %+v, want count=2 average=1e308 (only its own samples)",
			identitySig("cpu", nil), w1)
	}

	// 改一步长使三点分属不同窗口：各自的均值就是各自的存储值，互不干扰。
	pair2 := windowPairsFor("cpu", 1000, 2999, 500, nil)
	assertWindowPointsCorrespond(t, store, pair2)
	win2 := mustQueryWindows(t, store, pair2.windows)
	assertWindows(t, win2.Series[0].Windows, []Window{
		window(1000, 1499, 1, 1e16),
		window(1500, 1999, 2, -5e15), // (1 + -1e16)/2 精确平均
		window(2000, 2499, 1, 1e308),
		window(2500, 2999, 1, 1e308),
	}, "re-tiling isolates the cancellation points into their own windows")
}

// TestWindowsPointsNoMatchBothEmpty 没有区间内采样的序列在两边都不出现；
// 完全未命中时两种查询都成功返回空 series 数组（非 nil，序列化为 []）。
func TestWindowsPointsNoMatchBothEmpty(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, "["+
		sample("cpu", 1000, 2, map[string]string{"host": "a"})+","+
		sample("cpu", 2000, 4, map[string]string{"host": "a"})+","+
		sample("cpu", 2000, 5, map[string]string{"host": "b"})+"]")

	cases := []windowPair{
		windowPairsFor("nope", 0, 5000, 1000, nil),                              // 指标不存在（省略 labels）
		windowPairsFor("nope", 0, 5000, 1000, map[string]string{}),              // 指标不存在（显式 {}）
		windowPairsFor("cpu", 0, 5000, 1000, map[string]string{"host": "zzz"}),  // 标签值不匹配
		windowPairsFor("cpu", 0, 5000, 1000, map[string]string{"zone": "x"}),    // 缺少该标签键
		windowPairsFor("cpu", 1001, 1999, 100, nil),                             // 区间内没有点
		windowPairsFor("cpu", 2001, 9000, 1000, map[string]string{"host": "a"}), // 序列存在但区间在点之后
		windowPairsFor("cpu", 1000, 1000, 1, map[string]string{"host": "b"}),    // 标签命中但该时刻无点
		windowPairsFor("cpu", 1500, 1500, 1, nil),                               // start==end 落在空位置
	}
	for _, p := range cases {
		t.Run(p.note, func(t *testing.T) {
			assertWindowPointsCorrespond(t, store, p)
			win := mustQueryWindows(t, store, p.windows)
			det := mustQueryPoints(t, store, p.points)
			if win.Series == nil || len(win.Series) != 0 {
				t.Fatalf("windows series = %+v, want non-nil empty list", win.Series)
			}
			if det.Series == nil || len(det.Series) != 0 {
				t.Fatalf("detail series = %+v, want non-nil empty list", det.Series)
			}
			if raw := marshalCompact(t, win); raw != `{"status":"ok","op":"query_windows","series":[]}` {
				t.Fatalf("windows JSON = %s, want empty series []", raw)
			}
			if raw := marshalCompact(t, det); raw != `{"status":"ok","op":"query_points","series":[]}` {
				t.Fatalf("detail JSON = %s, want empty series []", raw)
			}
		})
	}
}

// TestWindowsPointsPartitionTable 表格驱动覆盖多种区间与步长组合：每个明细点
// 恰好计入一个窗口（划分性由通用核对里的计数总和保证），窗口边界始终从查询
// 起点平铺。包含负起点、start==end、step 大于区间宽度、step 为 1 等情形，
// 以及多条序列在同一组边界下各自缺少不同窗口的场景。
func TestWindowsPointsPartitionTable(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, "["+
		sample("m", -7, 1, map[string]string{"host": "a"})+","+
		sample("m", -3, 3, map[string]string{"host": "a"})+","+
		sample("m", 0, 5, map[string]string{"host": "a"})+","+
		sample("m", 4, 7, map[string]string{"host": "a"})+","+
		sample("m", 9, 9, map[string]string{"host": "a"})+","+
		sample("m", 12, 11, map[string]string{"host": "a"})+","+
		sample("m", -3, 30, map[string]string{"host": "b"})+","+ // 与 host=a 同时间戳
		sample("m", 8, 80, map[string]string{"host": "b"})+","+
		sample("other", 0, 999, nil)+"]")

	cases := []struct {
		name   string
		metric string
		start  int64
		end    int64
		step   int64
		labels map[string]string // nil = 省略 labels
	}{
		{"all labels full range step 5", "m", -10, 14, 5, nil},
		{"all labels step 1", "m", -7, 12, 1, nil},
		{"all labels step wider than range", "m", -10, 14, 1000, nil},
		{"host=a negative start step 3", "m", -8, 12, 3, map[string]string{"host": "a"}},
		{"host=a start==end on a sample", "m", 0, 0, 7, map[string]string{"host": "a"}},
		{"host=a start==end off samples", "m", 1, 1, 7, map[string]string{"host": "a"}},
		{"host=b shared tiling", "m", -10, 14, 5, map[string]string{"host": "b"}},
		{"host=a partial interior", "m", -3, 9, 4, map[string]string{"host": "a"}},
		{"other metric exact name", "other", -5, 5, 2, nil},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			assertWindowPointsCorrespond(t, store,
				windowPairsFor(c.metric, c.start, c.end, c.step, c.labels))
		})
	}

	// 点名核验一组非平凡窗口：[-10,14]、step 5 时边界为
	// [-10,-6]、[-5,-1]、[0,4]、[5,9]、[10,14]；host=a 的点 -7/-3/0/4/9/12
	// 依次落入窗口 0/1/2/2/3/4。
	win := mustQueryWindows(t, store, queryWindowsLabels("m", -10, 14, 5, map[string]string{"host": "a"}))
	assertWindows(t, win.Series[0].Windows, []Window{
		window(-10, -6, 1, 1),
		window(-5, -1, 1, 3),
		window(0, 4, 2, 6),
		window(5, 9, 1, 9),
		window(10, 14, 1, 11),
	}, "host=a tiling over a negative start")
}

// TestWindowsPointsInt64ExtremesCorrespond 起止时间与 step 接近 int64 上下界
// 时，窗口统计仍与明细逐条对应：复核侧用 big.Int 独立重算归属与边界，
// 不与统计侧共用任何溢出风险路径。
func TestWindowsPointsInt64ExtremesCorrespond(t *testing.T) {
	min := tsMinInt64
	max := tsMaxInt64
	store := NewMetricStore()
	mustOK(t, store, "["+
		sample("m", min, 3, nil)+","+
		sample("m", -2, 9, nil)+","+
		sample("m", -1, 1, nil)+","+
		sample("m", 0, 7, nil)+","+
		sample("m", max, 5, nil)+"]")

	cases := []windowPair{
		// 整个 int64 区间、step 为 MaxInt64：三个窗口，最后一个截到 end。
		windowPairsFor("m", min, max, max, nil),
		// step 为 1：每个时间戳独立窗口。
		windowPairsFor("m", min, max, 1, nil),
		// 负半区、巨大 step。
		windowPairsFor("m", min, -1, max, nil),
		// 跨零小区间、小步长。
		windowPairsFor("m", -2, 1, 1, nil),
		// start==end 在 int64 下界。
		windowPairsFor("m", min, min, max, nil),
		// start==end 在 int64 上界。
		windowPairsFor("m", max, max, max, nil),
	}
	for _, p := range cases {
		t.Run(p.note, func(t *testing.T) {
			assertWindowPointsCorrespond(t, store, p)
		})
	}

	// 点名核验极端组合的窗口边界：step=MaxInt64 时窗口为
	// [MinInt64,-2]、[-1,MaxInt64-2]、[MaxInt64-1,MaxInt64]。
	win := mustQueryWindows(t, store, queryWindowsAll("m", min, max, max))
	assertWindows(t, win.Series[0].Windows, []Window{
		window(min, -2, 2, 6),
		window(-1, max-2, 2, 4), // -1 上的 1 与 0 上的 7
		window(max-1, max, 1, 5),
	}, "full int64 range tiled with step MaxInt64")
}

package darksafe

import (
	"reflect"
	"testing"
)

// 本文件回归保障固定时间窗口均值查询（op 为 query_windows）成功结果的独立性：
// 业务代码通过 Go 入口取得 query_windows 的结果后，可以改动其中的指标名、标签、
// 窗口边界、点数、均值，增删窗口或调整窗口与序列条目的顺序供本次展示使用；
// 这些改动只能留在那一份返回结果中——
//
//   - 不能改变已写入的采样事实：按原名称与原标签再次查询，窗口边界、点数与
//     均值仍是真实保存数据对应的结果；改出来的名称、标签与窗口不会成为存储内容；
//   - 不能污染此前或此后取得的其他 query_windows 结果，同名不同标签的序列
//     之间也互不影响；
//   - 不能影响写入快照、query 区间统计与 query_points 采样明细；
//   - 不能影响后续写入的重复/冲突判定：对原位置提交不同值仍报告冲突，
//     冲突中的已存在值是真实保存的旧值，而不是结果里改出的窗口均值或其他数值。
//
// 无标签与某个标签值为空字符串仍是不同序列：向返回的空标签集合加键、删除返回
// 结果中的空值标签，都不能合并或改名真实序列。
//
// 两种 Go 入口都在保障范围内：专用入口 QueryWindowsLine 与统一逐行处理入口
// ProcessLine（后者以类型断言取得 *QueryWindowsResult）。与
// success_result_independent_test.go（写入快照与 query）和
// query_points_result_independent_test.go（query_points）的隔离测试相对应。

// findWindowsIndex 在窗口结果中找到指定指标名与完整标签集合的条目下标。
func findWindowsIndex(t *testing.T, res *QueryWindowsResult, name string, labels map[string]string) int {
	t.Helper()
	for i, v := range res.Series {
		if v.Name == name && reflect.DeepEqual(v.Labels, labels) {
			return i
		}
	}
	t.Fatalf("series %s %v not found in query_windows result: %+v", name, labels, res.Series)
	return -1
}

// assertWindowsFact 按给定查询再查一次窗口统计，断言结果恰好包含一条序列且其
// 窗口列表（边界、点数、均值、顺序）与预期完全一致。
func assertWindowsFact(t *testing.T, s *MetricStore, line string, want []Window, note string) {
	t.Helper()
	res := mustQueryWindows(t, s, line)
	if len(res.Series) != 1 {
		t.Fatalf("%s: series = %+v, want exactly one", note, res.Series)
	}
	assertWindows(t, res.Series[0].Windows, want, note)
}

// TestQueryWindowsMutationDoesNotChangeStorage 是核心隔离场景：同一指标多条标签
// 不同的序列，调用方拿到窗口结果后改名、增删改标签、篡改窗口边界/点数/均值、
// 增删窗口并调整窗口与序列条目的顺序，都只是在整理本地结果。存储事实、另一份
// 窗口结果、写入快照、query/query_points 与后续写入的重复/冲突判定都不受影响。
func TestQueryWindowsMutationDoesNotChangeStorage(t *testing.T) {
	s := NewMetricStore()
	// host=a：[1000,3000]、step 1000 下窗口 0 有两个点（均值 3）、
	// 中间窗口为空（省略）、收尾窗口一个点（值 8）。
	mustOK(t, s, `[
		{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":1500,"value":4,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":3000,"value":8,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":1000,"value":5,"labels":{"host":"b"}},
		{"name":"cpu","timestamp":1000,"value":6},
		{"name":"cpu","timestamp":1000,"value":7,"labels":{"zone":""}}
	]`)

	hostAWindows := []Window{
		window(1000, 1999, 2, 3),
		window(3000, 3000, 1, 8),
	}
	hostBWindows := []Window{window(1000, 1999, 1, 5)}
	noneWindows := []Window{window(1000, 1999, 1, 6)}
	zoneWindows := []Window{window(1000, 1999, 1, 7)}

	// 先保留一份未修改的窗口结果（全量 cpu），随后篡改另一份。
	kept := mustQueryWindows(t, s, queryWindowsAll("cpu", 1000, 3000, 1000))
	if len(kept.Series) != 4 {
		t.Fatalf("baseline query_windows = %+v, want 4 series", kept.Series)
	}
	res := mustQueryWindows(t, s, queryWindowsAll("cpu", 1000, 3000, 1000))

	// 调用方整理 host=a 条目：改名、改写标签、加标签，篡改两个窗口的边界、
	// 点数与均值，再交换窗口、截短并追加伪造窗口。
	a := &res.Series[findWindowsIndex(t, res, "cpu", map[string]string{"host": "a"})]
	a.Name = "cpu-renamed"
	a.Labels["host"] = "c"
	a.Labels["zone"] = "z"
	a.Windows[0].Start = 90001
	a.Windows[0].End = 91000
	a.Windows[0].Count = 90
	a.Windows[0].Average = 900
	a.Windows[1].Start = 80001
	a.Windows[1].End = 81000
	a.Windows[1].Count = 80
	a.Windows[1].Average = 800
	a.Windows[0], a.Windows[1] = a.Windows[1], a.Windows[0]
	a.Windows = append(a.Windows[:1], Window{Start: 1, End: 2, Count: 1, Average: 1})

	// 同伴序列 host=b 也被改名、改标签、篡改窗口。
	b := &res.Series[findWindowsIndex(t, res, "cpu", map[string]string{"host": "b"})]
	b.Name = "cpu-other"
	delete(b.Labels, "host")
	b.Labels["host"] = "d"
	b.Windows[0].Start = 77770
	b.Windows[0].End = 77779
	b.Windows[0].Count = 55
	b.Windows[0].Average = 555

	// 无标签与空值标签条目的标签也被改动。
	none := &res.Series[findWindowsIndex(t, res, "cpu", map[string]string{})]
	none.Labels["host"] = "x"
	emptyVal := &res.Series[findWindowsIndex(t, res, "cpu", map[string]string{"zone": ""})]
	delete(emptyVal.Labels, "zone")

	// 整理序列列表：交换条目、截短列表、追加伪造序列，并篡改信封字段。
	res.Series[0], res.Series[len(res.Series)-1] = res.Series[len(res.Series)-1], res.Series[0]
	res.Series = append(res.Series[:2], QueryWindowsSeries{
		Name:    "ghost",
		Labels:  map[string]string{"host": "g"},
		Windows: []Window{{Start: 4242, End: 4242, Count: 1, Average: 42}},
	})
	res.Status = "mutated"
	res.Op = "mutated"

	// host=a 条目的改动不能影响同伴序列：host=b 的事实仍是窗口 0 一点值 5。
	assertWindowsFact(t, s, queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "b"}),
		hostBWindows, "host=b fact after mutating host=a result")
	// 按原指标名、原标签、原区间查询，仍得到原始两个窗口（含被截掉的收尾窗口）。
	assertWindowsFact(t, s, queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "a"}),
		hostAWindows, "host=a fact after mutating its result")

	// 按仅在返回结果中改出的名称或标签查询，不应凭空出现数据或序列。
	for _, line := range []string{
		queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "c"}),
		queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "d"}),
		queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "g"}),
		queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "x"}),
		queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "a", "zone": "z"}),
		queryWindowsAll("cpu-renamed", 1000, 3000, 1000),
		queryWindowsAll("ghost", 1000, 3000, 1000),
	} {
		if qw := mustQueryWindows(t, s, line); len(qw.Series) != 0 {
			t.Fatalf("mutated identity %s must not match, got %+v", line, qw.Series)
		}
	}
	// 按改出的窗口边界查询，同样不应凭空出现窗口（窗口边界只由查询参数决定）。
	for _, line := range []string{
		queryWindowsLabels("cpu", 70000, 92000, 1000, map[string]string{"host": "a"}),
		queryWindowsLabels("cpu", 0, 100, 1000, map[string]string{"host": "a"}),
		queryWindowsAll("cpu-other", 70000, 80000, 10),
	} {
		if qw := mustQueryWindows(t, s, line); len(qw.Series) != 0 {
			t.Fatalf("mutated window bounds %s must not be stored, got %+v", line, qw.Series)
		}
	}

	// 先前保留的另一份窗口结果保留各自原有的标签、窗口与次序。
	wantKept := []struct {
		labels  map[string]string
		windows []Window
	}{
		{map[string]string{}, noneWindows},
		{map[string]string{"host": "a"}, hostAWindows},
		{map[string]string{"host": "b"}, hostBWindows},
		{map[string]string{"zone": ""}, zoneWindows},
	}
	if kept.Status != "ok" || kept.Op != "query_windows" || len(kept.Series) != len(wantKept) {
		t.Fatalf("retained query_windows envelope/series changed: %+v", kept)
	}
	for i, w := range wantKept {
		got := kept.Series[i]
		if got.Name != "cpu" || !reflect.DeepEqual(got.Labels, w.labels) {
			t.Fatalf("retained query_windows series[%d] identity = %+v, want cpu %v", i, got, w.labels)
		}
		assertWindows(t, got.Windows, w.windows, "retained query_windows series")
	}

	// 写入快照也保留原有标签与采样点，序列数仍是 4。
	snap := mustOK(t, s, `[]`)
	if len(snap.Series) != 4 {
		t.Fatalf("snapshot after query_windows mutation = %+v, want 4 series", snap.Series)
	}
	snapA := snap.Series[findViewIndex(t, snap, "cpu", map[string]string{"host": "a"})]
	if !reflect.DeepEqual(snapA.Points, []Point{
		{Timestamp: 1000, Value: 2},
		{Timestamp: 1500, Value: 4},
		{Timestamp: 3000, Value: 8},
	}) {
		t.Fatalf("snapshot host=a points = %+v", snapA.Points)
	}
	snapB := snap.Series[findViewIndex(t, snap, "cpu", map[string]string{"host": "b"})]
	if !reflect.DeepEqual(snapB.Points, []Point{{Timestamp: 1000, Value: 5}}) {
		t.Fatalf("snapshot host=b points = %+v, want (1000,5)", snapB.Points)
	}

	// 原序列、原时间戳、原值再次提交仍计为重复（存储认的是真实值，不是改出的均值）。
	dup := mustOK(t, s, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
	if dup.Added != 0 || dup.Duplicates != 1 {
		t.Fatalf("resubmit original host=a point = %+v, want one duplicate", dup)
	}
	dup = mustOK(t, s, `[{"name":"cpu","timestamp":1000,"value":5,"labels":{"host":"b"}}]`)
	if dup.Added != 0 || dup.Duplicates != 1 {
		t.Fatalf("resubmit original host=b point = %+v, want one duplicate", dup)
	}

	// 对同一位置提交不同值仍拒绝整批；冲突中的已存在值来自真实存储，不受返回
	// 结果里改出的窗口点数/均值影响（host=a 改出的 900、host=b 改出的 555）。
	lerr := mustFail(t, s, `[
		{"name":"cpu","timestamp":3000,"value":99,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":1000,"value":123,"labels":{"host":"a"}}
	]`)
	if lerr.Index != 1 || lerr.Conflict == nil {
		t.Fatalf("conflict must target the first conflicting point, got %+v", lerr)
	}
	c := lerr.Conflict
	if c.Series.Name != "cpu" || len(c.Series.Labels) != 1 || c.Series.Labels["host"] != "a" ||
		c.Timestamp != 3000 || c.Existing != 8 || c.Submitted != 99 {
		t.Fatalf("host=a conflict must report stored fact, got %+v", c)
	}
	lerr = mustFail(t, s, `[{"name":"cpu","timestamp":1000,"value":555,"labels":{"host":"b"}}]`)
	if lerr.Conflict == nil || lerr.Conflict.Existing != 5 || lerr.Conflict.Submitted != 555 {
		t.Fatalf("host=b conflict must report existing=5, got %+v", lerr.Conflict)
	}
	// 整批拒绝：本批没有任何点留下，3000 上的旧值仍在。
	if dup = mustOK(t, s, `[{"name":"cpu","timestamp":3000,"value":8,"labels":{"host":"a"}}]`); dup.Duplicates != 1 {
		t.Fatalf("conflict batch must not write anything, got %+v", dup)
	}

	// 区间统计与采样明细仍反映真实采样点，不跟随被改动的窗口结果变化。
	qr := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"a"}}`)
	if len(qr.Series) != 1 || qr.Series[0].Count != 3 || qr.Series[0].Average != 14.0/3.0 {
		t.Fatalf("host=a range query after mutation = %+v, want count=3 average=14/3", qr.Series)
	}
	qp := mustQueryPoints(t, s, `{"op":"query_points","name":"cpu","start":0,"end":10000,"labels":{"host":"b"}}`)
	if len(qp.Series) != 1 || !reflect.DeepEqual(qp.Series[0].Points, []Point{{Timestamp: 1000, Value: 5}}) {
		t.Fatalf("host=b detail query after mutation = %+v, want (1000,5)", qp.Series)
	}
}

// TestQueryWindowsEmptyAndEmptyValueLabelsIndependent 保留两种容易混淆的标签
// 身份：无标签序列与某个标签确实存在但值为空字符串的序列。给返回的空标签集合
// 加键、删除返回的空值标签、篡改返回窗口，都不能合并或改名这两条真实序列；
// 标签子集匹配与后续冲突判定仍按真实身份进行。
func TestQueryWindowsEmptyAndEmptyValueLabelsIndependent(t *testing.T) {
	s := NewMetricStore()
	mustOK(t, s, `[
		{"name":"cpu","timestamp":1000,"value":6},
		{"name":"cpu","timestamp":1000,"value":7,"labels":{"zone":""}},
		{"name":"cpu","timestamp":1000,"value":5,"labels":{"host":"b"}}
	]`)

	res := mustQueryWindows(t, s, queryWindowsAll("cpu", 1000, 3000, 1000))
	none := &res.Series[findWindowsIndex(t, res, "cpu", map[string]string{})]
	if none.Labels == nil {
		t.Fatal("query_windows labels for unlabeled series must be non-nil empty map")
	}
	emptyVal := &res.Series[findWindowsIndex(t, res, "cpu", map[string]string{"zone": ""})]

	// 调用方整理两个返回视图：空集合加键、空值标签删键、篡改窗口边界与统计。
	none.Labels["host"] = "x"
	none.Windows[0].Start = 6000
	none.Windows[0].End = 6999
	none.Windows[0].Count = 66
	none.Windows[0].Average = 66
	delete(emptyVal.Labels, "zone")
	emptyVal.Windows[0].Start = 5000
	emptyVal.Windows[0].End = 5999
	emptyVal.Windows[0].Count = 77
	emptyVal.Windows[0].Average = 77

	// 三条真实序列不被合并或改名：全量窗口查询仍是三条序列，统计各自不变。
	again := mustQueryWindows(t, s, queryWindowsAll("cpu", 1000, 3000, 1000))
	if len(again.Series) != 3 {
		t.Fatalf("full query_windows = %+v, want 3 distinct series", again.Series)
	}
	gotNone := again.Series[findWindowsIndex(t, again, "cpu", map[string]string{})]
	assertWindows(t, gotNone.Windows, []Window{window(1000, 1999, 1, 6)}, "unlabeled windows")
	gotEmpty := again.Series[findWindowsIndex(t, again, "cpu", map[string]string{"zone": ""})]
	assertWindows(t, gotEmpty.Windows, []Window{window(1000, 1999, 1, 7)}, "empty-value windows")

	// 原标签筛选仍成立：加出来的 host=x 不命中；空值标签筛选仍只命中真实空值序列。
	if qw := mustQueryWindows(t, s,
		queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "x"})); len(qw.Series) != 0 {
		t.Fatalf("added label must not match: %+v", qw.Series)
	}
	zoneEmpty := mustQueryWindows(t, s,
		queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"zone": ""}))
	if len(zoneEmpty.Series) != 1 ||
		!reflect.DeepEqual(zoneEmpty.Series[0].Labels, map[string]string{"zone": ""}) {
		t.Fatalf("empty-value label selection = %+v, want the zone='' series", zoneEmpty.Series)
	}
	assertWindows(t, zoneEmpty.Series[0].Windows, []Window{window(1000, 1999, 1, 7)},
		"empty-value selection windows")
	// 删除返回的空值标签后，空条件（{}）仍按全部序列返回，两条身份各自保留：
	// 无标签条目仍是空集合，zone="" 条目仍带该键，不会被合并成一条。
	allSeries := mustQueryWindows(t, s,
		queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{}))
	if len(allSeries.Series) != 3 {
		t.Fatalf("empty-label selection = %+v, want all 3 series with distinct identities", allSeries.Series)
	}
	if got := allSeries.Series[findWindowsIndex(t, allSeries, "cpu", map[string]string{})].Labels; len(got) != 0 {
		t.Fatalf("unlabeled identity must stay label-free, got %v", got)
	}
	zoneEntry := allSeries.Series[findWindowsIndex(t, allSeries, "cpu", map[string]string{"zone": ""})]
	if v, ok := zoneEntry.Labels["zone"]; !ok || v != "" || len(zoneEntry.Labels) != 1 {
		t.Fatalf("zone='' identity must keep its single key, got %v", zoneEntry.Labels)
	}
	// 改出的窗口区间不存在数据。
	if qw := mustQueryWindows(t, s,
		queryWindowsLabels("cpu", 5000, 6999, 1000, map[string]string{"zone": ""})); len(qw.Series) != 0 {
		t.Fatalf("mutated window range must not be stored: %+v", qw.Series)
	}

	// query 区间统计同样不合并两条序列。
	qr := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
	if len(qr.Series) != 3 {
		t.Fatalf("full average query = %+v, want 3 distinct series", qr.Series)
	}
	if q := qr.Series[findQueryIndex(t, qr, "cpu", map[string]string{})]; q.Count != 1 || q.Average != 6 {
		t.Fatalf("unlabeled average = %+v, want count=1 average=6", q)
	}
	if q := qr.Series[findQueryIndex(t, qr, "cpu", map[string]string{"zone": ""})]; q.Count != 1 || q.Average != 7 {
		t.Fatalf("empty-value average = %+v, want count=1 average=7", q)
	}

	// 后续写入仍按真实身份判定重复与冲突，冲突报告真实旧值而非改出的窗口均值。
	if dup := mustOK(t, s, `[{"name":"cpu","timestamp":1000,"value":6}]`); dup.Added != 0 || dup.Duplicates != 1 {
		t.Fatalf("unlabeled resubmit must duplicate, got %+v", dup)
	}
	lerr := mustFail(t, s, `[{"name":"cpu","timestamp":1000,"value":77,"labels":{"zone":""}}]`)
	if lerr.Conflict == nil || lerr.Conflict.Existing != 7 || lerr.Conflict.Submitted != 77 {
		t.Fatalf("empty-value conflict must report existing=7, got %+v", lerr.Conflict)
	}
}

// TestRetainedQueryWindowsStayFixedAfterNewWrite 任务书场景：区间 [1000,3000]、
// 窗口宽度 1000，原先只有 1000 与 3000 上的采样（两个非空窗口，中间窗口为空
// 被省略）；保留这份结果后成功写入 1500 与 2500 上的新点，新取得的结果更新
// 第一个窗口的点数与均值并出现原先为空的中间窗口，旧结果保持原来的两个窗口
// 及统计值。新旧结果中的标签也各自独立。
func TestRetainedQueryWindowsStayFixedAfterNewWrite(t *testing.T) {
	s := NewMetricStore()
	mustOK(t, s, `[
		{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":3000,"value":8,"labels":{"host":"a"}}
	]`)

	oldLine := queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "a"})
	old := mustQueryWindows(t, s, oldLine)
	oldWindows := []Window{
		window(1000, 1999, 1, 2),
		window(3000, 3000, 1, 8),
	}
	assertWindows(t, old.Series[0].Windows, oldWindows, "retained baseline windows")

	// 成功写入 1500->4 与 2500->6：第一窗口增加一点（均值变为 3），
	// 原先为空的中间窗口 [2000,2999] 出现一个点值 6。
	write := mustOK(t, s, `[
		{"name":"cpu","timestamp":1500,"value":4,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":2500,"value":6,"labels":{"host":"a"}}
	]`)
	if write.Added != 2 || write.Duplicates != 0 {
		t.Fatalf("new points write = %+v, want added=2", write)
	}

	fresh := mustQueryWindows(t, s, oldLine)
	newWindows := []Window{
		window(1000, 1999, 2, 3),
		window(2000, 2999, 1, 6),
		window(3000, 3000, 1, 8),
	}
	assertWindows(t, fresh.Series[0].Windows, newWindows, "new result reflects new points and the formerly empty window")

	// 之前保存的结果仍保持原来的两个窗口及统计值，不冒出中间窗口。
	if old.Status != "ok" || old.Op != "query_windows" || len(old.Series) != 1 {
		t.Fatalf("retained result envelope/series changed: %+v", old)
	}
	assertWindows(t, old.Series[0].Windows, oldWindows, "retained windows stay fixed after new write")

	// 新旧结果的标签集合各自独立：分别向两份结果加不同的标签，互不串扰，
	// 也不影响存储中的真实身份。
	old.Series[0].Labels["generation"] = "old"
	fresh.Series[0].Labels["generation"] = "new"
	if _, ok := old.Series[0].Labels["generation"]; !ok || old.Series[0].Labels["generation"] != "old" {
		t.Fatalf("old result labels changed unexpectedly: %v", old.Series[0].Labels)
